insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('edlsinnschdrossn', 'Edlsinnschdrossn', '', '', '', '', 'Edelsinnstraße', '[{"kategorie": "allg.", "text": "\"zentrale Straße im 12. Wiener Gemeindebezirk ([[Meidling]]), welche die Stadtteile [[Obermeidling]], [[Untermeidling]] und [[Hetzendorf]] miteinander verbindet\""}, {"kategorie": "", "text": "Sie beginnt bei der Meidlinger Hauptstraße und führt in Ost-West-Richtung bis zur Schönbrunner Allee"}, {"kategorie": "", "text": "Die Edelsinnstraße ist benannt nach dem Wohltätigkeitsverein \"Edelsinn\" (gegründet 1888), der sich humanitär um den 12. Bezirk große Verdienste erworben hat"}, {"kategorie": "", "text": "Die Edelsinnstraße ist eine wichtige Vedrkehrsachse im Bezirk. Die nahegelegene U-Bahn-Station [[Philadelphiabrücke]] (U6) bietet zudem eine direkte Anbindung an das Wiener U-Bahn-Netz."}]'::jsonb, ''),
  ('fasangoatnschdrossn', 'Fasangoatnschdrossn', '', '', '', '', 'Fasangartenstraße', '[{"kategorie": "allg.", "text": "Fasangarten (13), jenseits der Gloriette gelegener (südlicher) Teil des Schlossparks von Schönbrunn, der zu Jagdzwecken genützt wurde."}]'::jsonb, ''),
  ('wuehoemsschdrossn', 'Wühömsschdrossn', '', '', '', '', 'Wilhelmstraße', '[{"kategorie": "allg.", "text": "\"wichtige Verkehrsstraße im 12. Wiener Bezirk ([[Meidling]]), die eine zentrale Rolle als Verbindungsstraße innerhalb des Bezirks spielt\""}, {"kategorie": "", "text": "Sie verläuft durch Untermeidling bzw. [[Wilhelmsdorf]], einer einst selbstständigen Vorortegemeinde von Wien, die allerdings nur vier Jahre (von 1846 bis 1850) bestand"}, {"kategorie": "", "text": "Die Wilhelmstraße ist nach dem Propst von Klosterneuburg (1844-1853) und Hofprediger (ab 1820) Wilhelm Sedlacek (* 6. Juli 1793 Groß-Seelowitz, Mähren, † 30. Juni 1853) benannt, dem die Entstehung von [[Wilhelmsdorf]] zu verdanken ist"}, {"kategorie": "", "text": "Heute verläuft die Straße durch ein überwiegend urbanes Wohngebiet und ist von einer Mischung aus Wohnhäusern, Geschäften, öffentlichen Einrichtungen und dem angrenzenden [[Wilhelmsdorfer Park]] geprägt."}]'::jsonb, ''),
  ('wuehoemsduaf', 'Wühömsduaf', '', '', '', '', 'Wilhelmsdorf', '[{"kategorie": "allg.", "text": "einst selbständge Vorortgemeinde, die nur vier Jahre (1846-1850) Bestand hatte und heute Teil des zwölften Wiener Gemeindebezirks ([[Meidling]]) ist"}, {"kategorie": "", "text": "Die Vorortegemeinde Wilhelmsdorf befand sich auf dem Gebiet, das heute durch die Aßmayergasse, Eichen-, Dörfel- und [[Wilhelmstraße]] begrenzt wird"}, {"kategorie": "", "text": "ist nach dem Propst von Klosterneuburg (1844-1853) und Hofprediger (ab 1820) Wilhelm Sedlacek (* 6. Juli 1793 Groß-Seelowitz, Mähren, † 30. Juni 1853) benannt, dem die Entstehung von [[Wilhelmsdorf]] zu verdanken ist"}, {"kategorie": "", "text": "1846 beantragten die Bewohner bei der Grundherrschaft (Stift Klosterneuburg) die Abtrennung von [[Untermeidling]] und Anerkennung als selbständige Gemeinde, die nach dem Klosterneuburger Propst Wilhelm Sedlacek (1844-1853) Wilhelmsdorf benannt werden sollte. Die am 6. Juli 1846 gebildete Gemeinde besaß lediglich 46 Häuser."}]'::jsonb, ''),
  ('untameidling', 'Untameidling', '', '', '', '', 'Untermeidling', '[{"kategorie": "allg.", "text": "\"einst selbstständige Gemeinde und heute Teil des 12. Wiener Gemeindebezirks ([[Meidling]])\""}, {"kategorie": "", "text": "Untermeidling liegt südlich des [[Wienflusses]] im Nordosten von Meidling. Im Nordosten grenzt Untermeidling an den Bezirksteil [[Gaudenzdorf]], im Süden an den Bezirksteil [[Altmannsdorf]] und im Westen an den Bezirksteil [[Obermeidling]]"}, {"kategorie": "", "text": "1806 wurde der Wiener Vorort Meidling in Obermeidling und Untermeidling geteilt. Entsprechende Pläne bestanden bereits seit 1784. Das historische Zentrum Meidlings – gelegen an der [[Meidlinger]] Hauptstraße zwischen Lobkowitzbrücke und [[Tivoligasse]] – verblieb dabei bei Untermeidling. [[Gaudenzdorf]] wurde 1819 als eigene Gemeinde aus Untermeidling herausgelöst. 1846 folgte [[Wilhelmsdorf]], das jedoch vier Jahre später (1850) auf Grund mangelnder Finanzkraft wieder Untermeidling angeschlossen wurde"}, {"kategorie": "", "text": "Der heutige [[Meidlinger]] Friedhof, angelegt als gemeinsamer Friedhof der Gemeinden [[Untermeidling]], [[Obermeidling]] und [[Gaudenzdorf]], besteht seit 1862"}, {"kategorie": "", "text": "Heute ist Untermeidling ein dicht besiedelter, lebendiger Stadtteil im 12. Bezirk. Es gibt viele Wohnanlagen, Schulen, Einkaufsmöglichkeiten und öffentliche Einrichtungen. Im Süden des Bezirksteils erinnert die 1905 so benannte [[Unter-Meidlinger]] Straße an den Ort."}]'::jsonb, ''),
  ('obameidling', 'Obameidling', '', '', '', '', 'Obermeidling', '[{"kategorie": "allg.", "text": "\"einst selbstständige Gemeinde und heute Teil des 12. Wiener Gemeindebezirks ([[Meidling]])\""}, {"kategorie": "", "text": "Obermeidling befindet sich im Nordwesten des Gemeindebezirks südlich des [[Wienflusses]] am [[Grünen]] Berg. Die Lage Obermeidlings spiegelt sich auch in dessen Wappen wider: Ein goldenes Mühlrad steht für frühere Mühlen am Wienfluss, während im unteren Teil des Wappens ein grüner Berg abgebildet ist. Westlich von Obermeidling befindet sich das [[Schloss]] Schönbrunn. Im Osten grenzt Obermeidling an [[Untermeidling]] und im Süden an [[Hetzendorf]]"}, {"kategorie": "", "text": "1806 wurde der Wiener Vorort Meidling in Obermeidling und Untermeidling geteilt. Entsprechende Pläne bestanden bereits seit 1784. Die neue Gemeinde Obermeidling bestand aus einer Häuserzeile am „Anger an der Wien“ und aus Villen am Grünen Berg. Das dicht verbaute Gebiet wurde vom Wienfluss, der Grünbergstraße, der Tivoligasse und der Rotenmühlgasse begrenzt. Das historische Zentrum Meidlings – gelegen an der Meidlinger Hauptstraße zwischen Lobkowitzbrücke und Tivoligasse – fiel hingegen an Untermeidling"}, {"kategorie": "", "text": "1830 wurde im Süden von Obermeidling das Vergnügungsetablissement Tivoli eröffnet, dessen Betrieb 1967 eingestellt wurde. 1890/1892 wurde Obermeidling zu Wien eingemeindet und gehört seitdem zum 12. Wiener Gemeindebezirk ([[Meidling]])"}, {"kategorie": "", "text": "Heute ist Untermeidling ein dicht besiedelter, lebendiger Stadtteil im 12. Bezirk. Es gibt viele Wohnanlagen, Schulen, Einkaufsmöglichkeiten und öffentliche Einrichtungen."}]'::jsonb, ''),
  ('draschepark', 'Draschepark', '', '', '', '', 'Draschepark', '[{"kategorie": "allg.", "text": "\"große, weitläufige Parkanlage im 23. Wiener Gemeindebezirk ([[Liesing]]) im Stadtteil [[Inzersdorf]] mit einer Fläche von 134.000 m²\""}, {"kategorie": "", "text": "Er wird im Westen durch die [[Gutheil-Schoder-Gasse]], im Süden durch die [[Anton-Baumgartner-Straße]] und im Norden sowie Osten durch die Südosttangente (A23) begrenzt"}, {"kategorie": "", "text": "Der Park hat eine reiche historische Vergangenheit und ist nach der Adelsfamilie Drasche von Wartinberg benannt, die seit 1857 Eigentümer der beiden in der Nähe befindlichen Schlösser war, dem alten Schloss Inzersdorf und dem neuen Schloss Inzersdorf, die heute nicht mehr existieren"}, {"kategorie": "", "text": "Im 17. Jahrhundert wurde in Inzersdorf ein Wasserschloss erbaut, das später als altes Schloss Inzersdorf bekannt wurde. Im Jahr 1765 wurde das neue Schloss Inzersdorf südwestlich des alten Schlosses errichtet. Beide Schlösser waren in der Region bedeutende Bauwerke und prägten das Gebiet. Im Zweiten Weltkrieg wurde das neue Schloss 1944 durch Bombentreffer zerstört. Schließlich wurden die Reste beider Schlösser im Jahr 1965 abgetragen"}, {"kategorie": "", "text": "Der ursprüngliche Schlosspark, der im barocken Stil angelegt war, wurde im Laufe der Jahrhunderte verändert. Ein Teil des Parks wurde Ende des 20. Jahrhunderts durch den Bau der A23 (Südosttangente) und neuer Straßenzüge überbaut, was die Fläche des historischen Parks verkleinerte"}, {"kategorie": "", "text": "Heute besteht der Draschepark als öffentliche Parkanlage, die der Bevölkerung als Erholungsgebiet dient"}]'::jsonb, ''),
  ('drascheschdrossn', 'Drascheschdrossn', '', '', '', '', 'Draschestraße', '[{"kategorie": "allg.", "text": "\"wichtige Verkehrsstraße im Stadtteil [[Inzersdorf]] im 23. Wiener Bezirk ([[Liesing]]), die ihren Namen von der einflussreichen Familie Drasche von Wartinberg erhalten hat\""}, {"kategorie": "", "text": "Diese Familie war durch ihren Ziegelbrennereibetrieb zu großem Reichtum gelangt und seit 1857 Besitzer des ehemaligen Schlosses Inzersdorf und seiner Ländereien, zu denen auch der heutige [[Draschepark]] gehört"}, {"kategorie": "", "text": "Die Draschestraße verbindet die Laxenburgerstraße im 10. Bezirk ([[Favoriten]]) mit der [[Triester]] Straße und dem Draschepark in [[Liesing]] und hat sowohl historische als auch praktische Bedeutung für den Bezirk"}, {"kategorie": "", "text": "Entlang der Draschestraße befinden sich eine Mischung aus Gewerbe- und Industrieflächen, Wohngebieten sowie öffentlichen Einrichtungen. Besonders in den Gewerbegebieten der Draschestraße sind verschiedene Unternehmen und Industriebetriebe angesiedelt, was die Straße zu einem wichtigen wirtschaftlichen Standort im 23. Bezirk macht. Die Wohngegenden entlang der Straße sind durch Mehrfamilienhäuser und kleinere Wohnkomplexe geprägt."}]'::jsonb, ''),
  ('oaweitagossn', 'Oaweitagossn', '', '', '', '', 'Arbeitergasse', '[{"kategorie": "allg.", "text": "\"innerstädtische Straße mit historischer Bedeutung für die Arbeiterbewegung in Wien\""}, {"kategorie": "", "text": "Sie befindet sich im 5. Wiener Gemeindebezirk ([[Margareten]]) und verbindet den Margaretengürtel mit dem [[Schlossquadrat]]"}, {"kategorie": "", "text": "Die Arbeitergasse ist nach der 1871/72 errichteten Arbeiterwohnhausanlage \"Carolinum\", welche vom damaligen Maria-Elisabeth-Verein begründet wurde"}, {"kategorie": "", "text": "Der \"Maria-Elisabethen-Verein für freiwillige Armenpflege\" wurde am 8. Dezember 1854 in Wien gegründet. Zweck des Vereins war es, Arme und notleidenden Kranke in Wien zu unterstützen. Der Elisabethverein gehört zu den Gründungsvereinen der \"Centralstelle der katholischen Vereine für freiwillige Armenpflege\", aus der der Katholische Wohltätigkeitsverband für Niederösterreich und danach die Caritas hervorgingen"}, {"kategorie": "", "text": "Der Name \"Arbeitergasse\" spiegelt die historische Bedeutung der Arbeiterbewegung und der Industrialisierung in Wien wider. Der 5. Bezirk ([[Margareten]]) war historisch ein Stadtteil, der stark von der Arbeiterklasse geprägt wurde, besonders in der zweiten Hälfte des 19. Jahrhunderts, als viele Industriebetriebe und Fabriken in den Vororten Wiens angesiedelt waren. Die Arbeitergasse erinnert an die soziale und politische Bedeutung der Arbeiterbewegung, die besonders in dieser Zeit eine zentrale Rolle im gesellschaftlichen Wandel Wiens spielte"}, {"kategorie": "", "text": "Heute führt die Arbeitergasse durch ein dicht besiedeltes Wohngebiet und bietet eine gute Mischung aus Infrastruktur und Verkehrsanbindung."}]'::jsonb, ''),
  ('suewagossn', 'Süwagossn', '', '', '', '', 'Silbergasse', '[{"kategorie": "allg.", "text": "\"Straße im 19. Wiener Gemeindebezirk ([[Döbling]]), einem der noblen und grünen Bezirke Wiens\""}, {"kategorie": "", "text": "Sie beginnt bei der [[Billrothstraße]], verläuft durch den Bezirksteil [[Unterdöbling]] und ist nach dem hier am Krottenbach einst gelegenen Ried \"Silberäcker\" benannt"}, {"kategorie": "", "text": "In der Silbergasse befindet sich ein zentraler Bau [[Unterdöblings]], nämlich das [[Karmeliterkloster]] Döbling mit der dazugehörigen Kirche Hl. Familie"}, {"kategorie": "", "text": "In der Silbergasse endete früher auch eine historische Stiege, über welche man den Niveauunterschied zwischen Ober- und Unterdöbling überwand"}, {"kategorie": "", "text": "Es gibt auch einige historische Gebäude und gut erhaltene Altbauten, die das gehobene Ambiente der Gegend unterstreichen. Die Nähe zum [[Wienerwald]] macht die Silbergasse zu einem attraktiven Wohnort für Menschen, die Natur und Ruhe suchen, aber dennoch die Nähe zur Stadt schätzen."}]'::jsonb, ''),
  ('iglaseegossn', 'Iglaseegossn', '', '', '', '', 'Iglaseegasse', '[{"kategorie": "allg.", "text": "ruhige, grüne Wohnstraße im Stadtteil [[Unterdöbling]] im 19. Wiener Gemeindebezirk à(Döbling)"}, {"kategorie": "", "text": "Sie verläuft von der [[Grinzinger]] Allee bis zur [[Hohen]] Warte und ist nach der urkundlich bereits 1355 genannten Riedbezeichnung \"Egelsee\" benannt (eine tümpelreiche Gegend mit Egelvorkommen, deren Verbauung 1836 begann)"}, {"kategorie": "", "text": "Geprägt von Villen, Einfamilienhäusern und der Nähe zu den Weinbergen und dem Wienerwald, bietet die Gasse eine hohe Lebensqualität in einem der nobelsten Bezirke Wiens"}, {"kategorie": "", "text": "Die gute Anbindung an das öffentliche Verkehrsnetz sowie das ländliche Flair in unmittelbarer Nähe zur Stadt machen die Iglaseegasse zu einer beliebten Wohngegend für Menschen, die die Kombination aus Natur und Stadtleben schätzen."}]'::jsonb, ''),
  ('himmlhof', 'Himmlhof', '', '', '', '', 'Himmelhof', '[{"kategorie": "allg.", "text": "\"Naherholungsgebiet im 13. Wiener Gemeindebezirk ([[Hietzing]]), genauer im Bezirksteil [[Ober-Sankt-Veit]] (auch \"Zum Himmel\" genannt)\""}, {"kategorie": "", "text": "Von 1848 bis 1884 befand sich auf dieser Anhöhe eine Meierei, die von Franz Jauner begründet wurde und wegen ihrer schönen Aussicht und ihres vorzüglichen Oberskaffees sehr beliebt war"}, {"kategorie": "", "text": "Nach der Auflassung der Meierei und Restauration Himmelhof wurde ein Sanatorium errichtet, das 1962/1963 erweitert und in ein Bundeskonvikt für Knaben umgestaltet wurde"}, {"kategorie": "", "text": "Im Jahr 1948 wurde vom Ober-St.-Veiter Schiklub eine Schisprungschanze errichtet, auf der erstmals ein internationales Schispringen veranstaltet wurde. Diese Anlage brannte im Juni 1980 ab"}, {"kategorie": "", "text": "Heute ist der Himmelhof ein idyllisches und geschichtsträchtiges Gebiet am Rande des Wienerwalds, das vor allem für Naherholung, Wanderungen und Freizeitaktivitäten genutzt wird. Mit seiner grünen, hügeligen Landschaft und den weiten Ausblicken über Wien bietet der Himmelhof eine hohe Lebensqualität und ist ein wichtiger grüner Rückzugsort in einem der exklusivsten Bezirke Wiens."}]'::jsonb, ''),
  ('himmlhofgossn', 'Himmlhofgossn', '', '', '', '', 'Himmelhofgasse', '[{"kategorie": "allg.", "text": "\"ruhige, grüne Wohnstraße im 13. Wiener Gemeindebezirk ([[Hietzing]]), genauer im Bezirksteil [[Ober-Sankt-Veit]]\""}, {"kategorie": "", "text": "Sie ist nach dem [[Himmelhof]] benannt, einem Naherholungsgebiet zwischen Hacking (im [[Wiental]]) und dem Hackenberg (Hagenberg)"}, {"kategorie": "", "text": "Die Himmelhofgasse befindet sich in einem gehobenen Wohngebiet des 13. Bezirks, das vor allem von Villen und modernen Einfamilienhäusern dominiert wird. Die Gegend ist bekannt für ihre grüne Umgebung, die Nähe zum [[Wienerwald]] und den [[Himmelhof]], was sie zu einem attraktiven Wohnort für Familien und Menschen macht, die eine ruhige und naturnahe Lage schätzen."}]'::jsonb, ''),
  ('elisabethallee', 'Elisabethallee', '', '', '', '', 'Elisabethallee', '[{"kategorie": "allg.", "text": "\"ruhige Wohnstraße im 12. und 13. Wiener Gemeindebezirk ([[Meidling]] und [[Hietzing]]), welche sich vom [[Hetzendorfer]] Friedhof bis zum [[Hietzinger]] Friedhof und schließlich bis hinauf zum [[Küniglberg]] erstreckt\""}, {"kategorie": "", "text": "Sie ist nach Kaiserin Elisabeth ([[Sisi]]), der Gattin von [[Franz]] Joseph I. benannt. Elisabeth (1837-1898) war eine der bekanntesten Persönlichkeiten der Habsburger-Dynastie und ist für ihre Schönheit, ihre Liebe zur Natur und ihre tragische Geschichte berühmt"}, {"kategorie": "", "text": "Die Elisabethallee ist von grünen Gärten, alten Bäumen und gepflegten Häusern gesäumt, was der Gegend einen eleganten und ruhigen Charakter verleiht"}, {"kategorie": "", "text": "Die Umgebung der Elisabethallee ist bekannt für ihre großzügigen Grundstücke und repräsentativen Villen, die oft von wohlhabenden Familien bewohnt werden und durch ihre Nähe zum [[Schlosspark]] Schönbrunn und zum [[Küniglberg]] besonders begehrt sind."}]'::jsonb, ''),
  ('loryschdrossn', 'Loryschdrossn', '', '', '', '', 'Lorystraße', '[{"kategorie": "allg.", "text": "\"zentral gelegene Wohn- und Verbindungsstraße im 11. Wiener Gemeindebezirk ([[Simmering]]), die durch ein überwiegend urbanes Wohn- und Gewerbegebiet verläuft\""}, {"kategorie": "", "text": "Sie ist nach dem Wundarzt und Hausbesitzer Karl Lory (1794-1867) benannt, der wegen seiner Unterstützung der Armen durch \"milde Gaben\" und aufgrund seiner Verdienste um das Impfwesen, insbesondere um die Schutzimpfung gegen Pocken, als großer Wohltäter gilt"}, {"kategorie": "", "text": "In Anerkennung seines wohltätigen Wirkens wurde 1889 ein Straßenzug in seiner Heimatgemeinde nach ihm benannt"}, {"kategorie": "", "text": "1907 wurden seine sterblichen Überreste in ein ehrenhalber gewidmetes Grab am [[Simmeringer]] Friedhof überführt."}]'::jsonb, ''),
  ('untadoebling', 'Untadöbling', '', '', '', '', 'Unterdöbling', '[{"kategorie": "allg.", "text": "\"historischer Teil des 19. Wiener Gemeindebezirks ([[Döbling]]), der ursprünglich \"Krottendorf\" hieß und dessen Entstehung bis ins 9. Jahrhundert zurückreicht\""}, {"kategorie": "", "text": "Unterdöbling war bis 1892 eine eigenständige Gemeinde und ist heute ein Stadtteil Wiens sowie eine der 89 Wiener Katastralgemeinden"}, {"kategorie": "", "text": "Döbling wurde erstmals 1114 als de Teopilic urkundlich erwähnt. Sein Name leitet sich vom altslawischen \"toplica\" ab, was so viel wie „warmer Bach“ bedeutet. Spätere Schreibweisen des Ortsnamens waren beispielsweise Toblich, Töbling und Tepling. Ursprünglich hieß Unterdöbling jedoch auf Grund seiner Lage am Krottenbach Chrottendorf, erst im 15. Jahrhundert kam der spätere Name auf"}, {"kategorie": "", "text": "Die Niveauunterschiede zwischen Unterdöbling und [[Oberdöbling]], konkret zwischen der heutigen [[Billrothstraße]] (früher \"Hirschengasse\") und der [[Silbergasse]] wurden einst durch eine Stiege (mit anschließender Bachbrücke) überwunden"}, {"kategorie": "", "text": "Unterdöbling wurde während der beiden Türkenbelagerungen (1529 und 1683) verwüstet, ebenso wie auch durch die Franzosen 1805 und 1809.  6. In der Biedermeierzeit errichteten dann wohlhabende Wiener Bürger in Unterdöbling ihre Landhäuser. Der Krottenbach wurde eingewölbt, womit die optische Trennung von [[Oberdöbling]] und die dorthin führende Bachbrücke wegfielen"}, {"kategorie": "", "text": "Unterdöbling verfügt durch die im orientalischen Stil ausgeführte moscheeähnliche, ehemalige Insektenpulverfabrik des Johann Zacherl, die [[Zacherlfabrik]], über ein einzigartiges Bauwerk. Ein weiterer zentraler Bau Unterdöblings ist das [[Karmeliterkloster]] Döbling in der [[Silbergasse]] mit d+B10419er dazugehörigen Kirche Hl. Familie. Auch einige ehemalige Weinhauerhäuser findet man noch in Unterdöbling"}, {"kategorie": "", "text": "Der ehemalige Ortsfriedhof mit den Grabstätten von Johann Strauss (Vater) und Joseph Lanner lag ebenfalls in Unterdöbling, wurde jedoch 1927 aufgelassen. Während ihre Gebeine auf den Wiener Zentralfriedhof umgebettet wurden, bezog man die beiden Grabsteine in den auf dem Gelände gestalteten [[Strauß-Lanner-Park]] mit ein"}, {"kategorie": "", "text": "Heute ist Unterdöbling ein charmant-dörflicher Teil Wiens, der sich durch seine ruhige Wohnlage, die Nähe zur Natur und seine gute Verkehrsanbindung auszeichnet."}]'::jsonb, ''),
  ('obadoebling', 'Obadöbling', '', '', '', '', 'Oberdöbling', '[{"kategorie": "allg.", "text": "\"historischer Teil des 19. Wiener Gemeindebezirks ([[Döbling]]), der im Süden des Bezirks liegt und dessen Entstehung bis in die Römerzeit zurückreicht\""}, {"kategorie": "", "text": "Oberdöbling war die ältere von zwei Ansiedlungen (Oberdöbling und [[Unterdöbling]]), lag geographisch höher als Unterdöbling und gab sowohl dem gesamten Vorort als auch dem späteren 19. Bezirk Döbling den Namen. Die hohe freie Lage wurde bereits von den Römern als strategisch wertvoll erkannt (ein römischer Wachtturm zum Schutz der Heerstraße befindet sich hinter Döblinger Hauptstraße 26)"}, {"kategorie": "", "text": "Oberdöbling war bis 1892 eine eigenständige Gemeinde und ist heute ein Stadtteil Wiens sowie eine der 89 Wiener Katastralgemeinden"}, {"kategorie": "", "text": "Döbling wurde erstmals 1114 als de Teopilic urkundlich erwähnt. Sein Name leitet sich vom altslawischen \"toplica\" ab, was so viel wie „warmer Bach“ bedeutet. Spätere Schreibweisen des Ortsnamens waren beispielsweise Toblich, Töbling und Tepling"}, {"kategorie": "", "text": "Die Niveauunterschiede zwischen Unterdöbling und [[Oberdöbling]], konkret zwischen der heutigen [[Billrothstraße]] (früher \"Hirschengasse\") und der [[Silbergasse]] wurden einst durch eine Stiege (mit anschließender Bachbrücke) überwunden"}, {"kategorie": "", "text": "Oberdöbling wurde während der beiden Türkenbelagerungen (1529 und 1683) verwüstet, ebenso wie auch durch die Franzosen 1805 und 1809. In der Biedermeierzeit errichteten dann wohlhabende Wiener Bürger in Oberdöbling ihre Landhäuser. Der Krottenbach wurde eingewölbt, womit die optische Trennung von [[Unterdöbling]] und die dorthin führende Bachbrücke wegfielen"}, {"kategorie": "", "text": "Ein eigenes Siegel des Dorfes Oberdöbling ist von 1694 überliefert. Es zeigt den heiligen Jakob mit der Inschrift \"Sigil der gemain Ober Döbling 1694\". Dieses Siegel war 1904 auch Grundlage für die Gestaltung des Bezirkswappens Döbling"}, {"kategorie": "", "text": "Im Westen des Oberdöblinger Gebiets, nördlich der [[Krottenbachstraße]], bildete sich Anfang des 20. Jahrhunderts ein Armenviertel, das [[Krim]] genannt wurde. In der Nachkriegszeit der 1950er Jahre erlebte die [[Krim]] eine \"Assanierung\" (Stadterneuerung), vorhandene Gebäude wurden saniert und zugleich wurden zahlreiche Gemeindebauten und eine eigene Pfarrkirche errichtet. 9. Heute ist Oberdöbling ein charmant-dörflicher Teil Wiens, der sich durch seine ruhige Wohnlage, die Nähe zur Natur und seine gute Verkehrsanbindung auszeichnet."}]'::jsonb, ''),
  ('zachalfabrik', 'Zachalfabrik', '', '', '', '', 'Zacherlfabrik', '[{"kategorie": "allg.", "text": "\"historisches Industriegebäude an der Nusswaldgasse 14 im 19. Wiener Gemeindebezirk ([[Döbling]])\""}, {"kategorie": "", "text": "Die Zacherlfabrik wurde von Johann Zacherl gebaut, der im 19. Jahrhundert durch die Herstellung und den Vertrieb von Insektenpulver, das aus der Chrysantheme gewonnen wurde, zu großem Wohlstand gelangte. Zacherl brachte das Mittel aus dem Orient nach Wien und konnte damit eine internationale Kundschaft bedienen. Das Produkt war besonders zur Bekämpfung von Motten und anderen Schadinsekten beliebt"}, {"kategorie": "", "text": "Das Gebäude selbst wurde zwischen 1888 und 1892 nach den Plänen des Architekten Hugo von Wiedenfeld errichtet. Es zeichnet sich durch eine neomaurische Architektur aus, die durch den Einfluss des Orients geprägt ist, was auf die Handelsbeziehungen Zacherls mit dem Orient hinweist. Die Fassaden der Zacherlfabrik erinnern an orientalische Architektur mit gegliederten Ziegelmustern und bögenartigen Fenstern"}, {"kategorie": "", "text": "Das Bauwerk hat eine repräsentative Fassade mit orientalisch inspirierten Elementen, was im industriellen Wien des 19. Jahrhunderts außergewöhnlich war. Die Backsteinfassade, die bogenförmigen Fenster und die verzierten Türme verleihen dem Gebäude ein einzigartiges Erscheinungsbild, das sich stark von anderen Industriegebäuden dieser Zeit abhebt"}, {"kategorie": "", "text": "Die Fabrik galt als hochmodern und innovativ in Bezug auf die technische Ausstattung und die architektonische Gestaltung. Sie diente nicht nur als Produktionsstätte, sondern war auch ein Symbol für den wirtschaftlichen Erfolg und die internationale Ausrichtung des Unternehmens"}, {"kategorie": "", "text": "Obwohl die Zacherlfabrik ihren Betrieb als Produktionsstätte für Insektenpulver längst eingestellt hat, ist das Gebäude heute ein denkmalgeschütztes und bedeutendes industrielles Kulturerbe. Es wird heute hauptsächlich als Kultur- und Veranstaltungsort genutzt."}]'::jsonb, ''),
  ('heibeag', 'Heibeag', '', '', '', '', 'Heuberg', '[{"kategorie": "allg.", "text": "\"Erhebung im 17. Wiener Gemeindebezirk ([[Hernals]]), die eine Höhe von etwa 464 Metern erreicht, zu den nördlichen Ausläufern des [[Wienerwalds]] gehört\""}, {"kategorie": "", "text": "Der Heuberg befindet sich nahe der Stadtteile [[Neuwaldegg]] und [[Dornbach]] und ist wohl nach der einstigen Heugewinnung in diesem Gelände benannt"}, {"kategorie": "", "text": "Das Gebiet rund um den Heuberg war in der Vergangenheit sowohl als Sommerfrische als auch als Wohngebiet beliebt. In der Umgebung befinden sich Villen, Einfamilienhäuser und Gartenanlagen, die das Gebiet zu einer exklusiven Wohngegend machen. Besonders im späten 19. und frühen 20. Jahrhundert war der Heuberg ein beliebter Rückzugsort für wohlhabende Wiener Familien"}, {"kategorie": "", "text": "Im Laufe der Geschichte gab es auf dem Heuberg verschiedene Siedlungsprojekte, und auch heute ist das Gebiet rund um den Heuberg durch gehobene Wohnanlagen und Villenviertel geprägt. Die Nähe zur Natur und die gute Anbindung an die Stadt machen das Gebiet sowohl für Erholungssuchende als auch für Bewohner attraktiv."}]'::jsonb, ''),
  ('koinbeagaduaf', 'Koinbeagaduaf', '', '', '', '', 'Kahlenbergerdorf', '[{"kategorie": "allg.", "text": "kleiner, historischer Stadtteil im 19. Wiener Gemeindebezirk ([[Döbling]]), der am Fuße des [[Kahlenbergs]] und des [[Leopoldsbergs]] liegt, zwei prominente Erhebungen im [[Wienerwald]], die bekannte Ausflugsziele sind"}, {"kategorie": "", "text": "Das Kahlenbergerdorf grenzt direkt an die [[Donau]] und liegt nördlich des Stadtzentrums von Wien"}, {"kategorie": "", "text": "Das Kahlenbergerdorf ist eines der ältesten Dörfer in Wien. Es wurde bereits im 12. Jahrhundert urkundlich erwähnt und hat sich seinen dörflichen Charakter bis heute weitgehend bewahrt"}, {"kategorie": "", "text": "Der Stadtteil ist geprägt von historischen Gebäuden, darunter traditionelle Wiener Winzerhäuser und enge Gassen, die an das mittelalterliche Dorfleben erinnern. Die [[Kirche]] St. Georg aus dem 14. Jahrhundert ist ein weiteres markantes Bauwerk des Ortes"}, {"kategorie": "", "text": "Das Kahlenbergerdorf hat eine lange Tradition im Weinanbau, die bis ins Mittelalter zurückreicht. Auch heute noch gibt es in und um das Dorf Weingärten, und die Region ist bekannt für ihre [[Heurigen]], traditionelle Wiener Weinlokale, wo lokaler Wein und typische Wiener Speisen serviert werden."}]'::jsonb, ''),
  ('poetzleinsduaf', 'Pötzleinsduaf', '', '', '', '', 'Pötzleinsdorf', '[{"kategorie": "allg.", "text": "Stadtteil im 18. Wiener Gemeindebezirk ([[Währing]]). Es liegt im nordwestlichen Teil Wiens, am Rande des [[Wienerwalds]], und ist bekannt für seine grünen, gehobenen Wohngegenden, die Nähe zur Natur und historische Villen. Pötzleinsdorf gilt als eine der exklusiveren Wohngegenden Wiens und bietet eine Mischung aus städtischem Komfort und ländlicher Idylle"}, {"kategorie": "", "text": "Pötzleinsdorf grenzt im Westen an den Wienerwald, im Süden an den Stadtteil [[Gersthof]] und im Osten an das zentrale Währing"}, {"kategorie": "", "text": "Pötzleinsdorf war ursprünglich ein kleines Dorf, das bereits im Mittelalter bestand. Der Name \"Pötzleinsdorf\" leitet sich von einem früheren Besitzer namens „Petzl“ ab. Im Jahr 1892 wurde Pötzleinsdorf zusammen mit anderen Vororten in die Stadt Wien eingemeindet und Teil des neu geschaffenen 18. Bezirks, Währing. Im Laufe der Jahrhunderte entwickelte sich der Ort zu einem beliebten Rückzugsort für wohlhabende Wiener"}]'::jsonb, ''),
  ('augoatnviatl', 'Augoatnviatl', '', '', '', '', 'Augartenviertel', '[{"kategorie": "allg.", "text": "Stadtteil im 2. Wiener Gemeindebezirk ([[Leopoldstadt]]). Es befindet sich rund um den [[Augarten]], einen der ältesten und bekanntesten Barockgärten Wiens. Das Viertel ist geprägt von seiner Nähe zu diesem großen, historischen Park, der eine zentrale Rolle im kulturellen und sozialen Leben der Umgebung spielt"}, {"kategorie": "", "text": "Das Augartenviertel liegt im westlichen Teil des Bezirks Leopoldstadt, direkt an der Grenze zum 20. Bezirk, Brigittenau. Der namensgebende [[Augarten]] bildet das Herzstück des Viertels und ist von Wohngebieten, kulturellen Einrichtungen und Schulen umgeben"}, {"kategorie": "", "text": "Das Augartenviertel ist eine gemischte Wohngegend, die eine Kombination aus historischen Gebäuden, insbesondere aus der [[Gründerzeit]], und modernen Wohnbauten bietet. Viele der Altbauten sind gut erhalten und begehrt, was das Viertel zu einem attraktiven Wohnort macht."}]'::jsonb, ''),
  ('augoatn', 'Augoatn', '', '', '', '', 'Augarten', '[{"kategorie": "allg.", "text": "historischer Barockgarten im 2. Wiener Gemeindebezirk ([[Leopoldstadt]]). Er ist einer der ältesten und bedeutendsten öffentlichen Parks in Wien und hat eine lange Geschichte, die eng mit der Kultur und Entwicklung der Stadt verbunden ist"}, {"kategorie": "", "text": "Der Augarten erstreckt sich über eine Fläche von etwa 52 Hektar und bietet eine Kombination aus gepflegten Gartenanlagen, weitläufigen Wiesen und bedeutenden kulturellen Einrichtungen"}, {"kategorie": "", "text": "Der Augarten geht auf das 17. Jahrhundert zurück, als das Gelände erstmals als Lustgarten für den Adel genutzt wurde. Im Jahr 1614 ließ [[Kaiser]] Matthias hier ein Jagdschloss errichten, das später durch die Habsburger erweitert wurde;  4."}]'::jsonb, ''),
  ('hochschdaedtplotz', 'Hochschdädtplotz', '', '', '', '', 'Hochstädtplatz', '[{"kategorie": "allg.", "text": "zentraler Platz im 20. Wiener Gemeindebezirk ([[Brigittenau]])"}, {"kategorie": "", "text": "Er liegt im nördlichen Teil des Bezirks und bildet einen wichtigen Verkehrsknotenpunkt für den Individualverkehr sowie den öffentlichen Nahverkehr"}, {"kategorie": "", "text": "Der Platz wurde nach der Schlacht von Höchstädt benannt, die 1704 im Spanischen Erbfolgekrieg stattfand (Sieg der Österreicher am 13. August 1704 im Spanischen Erbfolgekrieg unter Prinz Eugen über die Bayern und Franzosen)"}, {"kategorie": "", "text": "Der Name des Platzes galt Eingeweihten nach 1945 jahrzehntelang als ein vertrauter Hinweis auf die Kommunistische Partei Österreichs (KPÖ), die hier im Gebäude ihres Globus-Verlags ihren Sitz hatte."}]'::jsonb, ''),
  ('heimwea', 'Heimwea', '', '', '', '', 'Heimwehr', '[{"kategorie": "allg.", "text": "\"rechtsextreme, paramilitärische Bewegung in Österreich, die in der Zeit der [[Ersten]] Republik (1918–1938) aktiv war\""}, {"kategorie": "", "text": "Sie wurde in den frühen 1920er Jahren als Reaktion auf die politischen und sozialen Umwälzungen nach dem [[Ersten]] Weltkrieg gegründet und spielte eine zentrale Rolle in den politischen Auseinandersetzungen zwischen den konservativen und sozialdemokratischen Kräften"}, {"kategorie": "", "text": "Die Heimwehr stand ideologisch dem Faschismus nahe und unterstützte die Abschaffung der Demokratie zugunsten eines autoritären Ständestaats"}, {"kategorie": "", "text": "Ideologisch stand die Heimwehr für Antimarxismus, Antiliberalismus und eine autoritäre Staatsordnung. Sie lehnte die parlamentarische Demokratie und die Verfassung der Ersten Republik ab und strebte einen korporativen [[Ständestaat]] an, in dem soziale Klassen nicht durch Wahlen, sondern durch ständische Vertretungen organisiert werden sollten"}, {"kategorie": "", "text": "In den 1930er Jahren orientierte sich die Heimwehr zunehmend an den Ideen des italienischen Faschismus unter Benito Mussolini. Die Mitglieder der Heimwehr sahen in der sozialistischen Arbeiterbewegung, insbesondere in der Sozialdemokratischen Partei und dem [[Republikanischen]] Schutzbund, eine Bedrohung für ihre Werte und ihre Vorstellung einer ständischen, autoritären Gesellschaftsordnung"}, {"kategorie": "", "text": "Die Heimwehr wurde zunehmend in die politischen Konflikte der [[Ersten]] Republik verwickelt und stellte sich als Gegengewicht zum sozialdemokratischen [[Republikanischen]] Schutzbund auf. Die beiden Gruppierungen standen sich in zahlreichen gewalttätigen Auseinandersetzungen gegenüber. Diese Kämpfe fanden ihren Höhepunkt in den [[Februarkämpfen]] von 1934, bei dem die [[Heimwehr]] auf der Seite der konservativen Regierung stand"}, {"kategorie": "", "text": "Nach dem Scheitern des sozialdemokratischen Aufstands spielte die Heimwehr eine Schlüsselrolle bei der Errichtung des Austrofaschistischen [[Ständestaates]]. Die Bewegung unterstützte die Diktatur von Engelbert Dollfuß und später Kurt Schuschnigg und war maßgeblich an der Auflösung der demokratischen Verfassung beteiligt"}, {"kategorie": "", "text": "Die Heimwehr verlor ab 1936 an Einfluss, als die Nationalsozialisten in Österreich immer stärker wurden. Viele Mitglieder der Heimwehr, die ursprünglich dem [[Ständestaat]] nahegestanden hatten, wandten sich der NSDAP zu. Die Bewegung löste sich nach dem \"Anschluss\" Österreichs an Nazi-Deutschland im Jahr 1938 endgültig auf, als die Nationalsozialisten alle paramilitärischen Organisationen des Ständestaats verboten"}]'::jsonb, ''),
  ('schdaendeschdoot', 'Schdändeschdoot', '', '', '', '', 'Ständestaat', '[{"kategorie": "allg.", "text": "\"autoritäre Regierungsform, die in Österreich zwischen 1934 und 1938 bestand\""}, {"kategorie": "", "text": "Diese Regierungsform wird auch als [[Austrofaschismus]] bezeichnet und wurde nach den [[Februarkämpfen]] von 1934 von der konservativen Regierung unter Engelbert Dollfuß eingeführt"}, {"kategorie": "", "text": "Der Ständestaat beruhte auf der Idee eines korporativen Staates, in dem politische Parteien abgeschafft und die Gesellschaft in berufsständische Gruppen (Stände) organisiert wurde"}, {"kategorie": "", "text": "Nach den [[Februarkämpfen]] von 1934, bei dem die Sozialdemokratie und ihr paramilitärischer Flügel, der [[Republikanische]] Schutzbund, von den Regierungstruppen der [[Heimwehr]] und dem Bundesheer besiegt wurden, wurde die demokratische Verfassung von 1920 außer Kraft gesetzt"}, {"kategorie": "", "text": "Am 1. Mai 1934 wurde eine neue autoritäre Verfassung verabschiedet, die den parlamentarischen Rechtsstaat durch ein ständisches System ersetzte. Diese Verfassung orientierte sich an den Ideen des italienischen Faschismus und sah die Gesellschaft nicht als eine Gemeinschaft von Individuen, sondern als eine Gliederung in verschiedene Stände, also berufsbezogene Interessenvertretungen"}, {"kategorie": "", "text": "Die Gesellschaft war in verschiedene berufsständische Körperschaften (z.B. für Arbeiter, Unternehmer, Bauern) unterteilt, die die Interessen ihrer Mitglieder vertreten sollten. Diese Körperschaften sollten die politische Repräsentation ersetzen, sodass Parteien als politische Vertretungen überflüssig wurden"}, {"kategorie": "", "text": "Politische Parteien wurden verboten, die katholische Kirche wurde zur Staatskirche erhoben, die Medien wurden kontrolliert, und die politischen Gegner, vor allem Sozialisten und Kommunisten, wurden verfolgt, inhaftiert oder ins Exil gezwungen"}, {"kategorie": "", "text": "Der Ständestaat endete mit dem [[Anschluss]] Österreichs an Nazi-Deutschland im März 1938. Unter starkem Druck der Nationalsozialisten, die bereits 1934 einen Putschversuch unternommen hatten, wurde die Regierung von Kurt Schuschnigg gestürzt, und Österreich wurde in das nationalsozialistische [[Deutsche]] Reich eingegliedert. Mit dem [[Anschluss]] erlosch auch die Idee des Ständestaates, da das Land nun Teil eines faschistischen Staates mit einer totalitären Ideologie wurde"}]'::jsonb, ''),
  ('schdaendeschdootsvafossung', 'Schdändeschdootsvafossung', '', '', '', '', 'Ständestaatsverfassung', '[{"kategorie": "allg.", "text": "\"die Verfassung Österreichs von 1934 bis 1938, die während des [[Austro-Faschismus]] unter der Regierung von Engelbert Dollfuß eingeführt wurde\""}, {"kategorie": "", "text": "Durch diese Verfassung wurde ein autoritärer, korporatistischer Staat begründet, der sich an das katholische Sozialverständnis anlehnte"}, {"kategorie": "", "text": "Der Ständestaat wurde in Stände, also Berufs- und Interessenvertretungen, unterteilt, die die gesellschaftlichen Gruppen wie Arbeiter, Bauern und Unternehmer repräsentierten"}, {"kategorie": "", "text": "Die parlamentarische Demokratie wurde abgeschafft, politische Parteien verboten, und die Macht lag bei der [[Vaterländischen]] Front, der einzigen zugelassenen politischen Organisation."}]'::jsonb, ''),
  ('tivoligossn', 'Tivoligossn', '', '', '', '', 'Tivoligasse', '[{"kategorie": "allg.", "text": "\"traditionsreiche Straße im 12. Wiener Gemeindebezirk ([[Meidling]]), die ihren Namen dem ehemaligen Vergnügungspark Tivoli verdankt\""}, {"kategorie": "", "text": "Dieser Park, der im 19. Jahrhundert in der Nähe des Schlosses Schönbrunn lag, war ein beliebter Erholungsort für die Wiener Bevölkerung"}, {"kategorie": "", "text": "Der Tivoli-Vergnügungspark, der der Straße ihren Namen gab, existierte von 1830 bis 1863 und bot verschiedene Attraktionen wie Theateraufführungen, Konzerte und Tanzveranstaltungen. Der Park war ein Vorläufer moderner Freizeitparks und spielte eine wichtige Rolle im gesellschaftlichen Leben der Wiener"}, {"kategorie": "", "text": "Nachdem der Park geschlossen wurde, wurde das Gebiet größtenteils bebaut, und die Straße, die später nach dem Park benannt wurde, entstand. Heute erinnert nur noch der Straßenname an die glanzvolle Vergangenheit dieses beliebten Ausflugsziels"}, {"kategorie": "", "text": "Heute verläuft die Tivoligasse durch Ober- und Untermeidling und durchquert hauptsächlich Wohngebiete. Entlang der Straße befinden sich zahlreiche Wohnhäuser, Schulen und öffentliche Einrichtungen"}, {"kategorie": "", "text": "Ihre Nähe zu Sehenswürdigkeiten wie dem [[Schlosspark]] Schönbrunn macht sie zu einer begehrten Wohngegend."}]'::jsonb, ''),
  ('habsbuagamonachii', 'Habsbuagamonachii', '', '', '', '', 'Habsburgermonarchie', '[{"kategorie": "allg.", "text": "\"Bezeichnung für die Herrschaftsgebiete der [[Habsburgerdynastie]], die über mehrere Jahrhunderte weite Teile Europas regierte\""}, {"kategorie": "", "text": "Sie begann im 13. Jahrhundert mit der Wahl von Rudolf I. zum römisch-deutschen König und entwickelte sich zu einem territorial und politisch dominanten Gebilde, das Gebiete in Mittel- und Osteuropa, Italien, Spanien und den Niederlanden umfasste"}, {"kategorie": "", "text": "Die Habsburgermonarchie war ein Vielvölkerstaat, der zahlreiche ethnische Gruppen und Sprachen umfasste, darunter Deutsche, Ungarn, Tschechen, Slowaken, Kroaten, Italiener, Polen und viele andere. Diese multinationale Struktur war sowohl eine Stärke als auch eine Schwäche, da sie kulturellen Reichtum brachte, aber auch zu Spannungen und Konflikten zwischen den Völkern führte"}, {"kategorie": "", "text": "Die Habsburger versuchten, ihre Macht zentral zu festigen, besonders unter den Kaisern des 16. und 17. Jahrhunderts. Die Monarchie entwickelte sich zu einem absolutistischen Herrschaftsmodell, insbesondere unter den Kaisern [[Leopold]] I., [[Karl]] VI. und [[Maria]] Theresia, die ihre Macht über die Länder konsolidierten und direkte Kontrolle über Verwaltung und Gesetzgebung ausübten"}, {"kategorie": "", "text": "Die Monarchie war stark vom Katholizismus geprägt. Die Habsburger betrachteten sich als Verteidiger des Katholizismus, was sich insbesondere während der Gegenreformation und im Kampf gegen den Protestantismus zeigte. Dies führte zu zahlreichen religiösen Konflikten, insbesondere im [[Dreißigjährigen]] Krieg"}, {"kategorie": "", "text": "Die Habsburger festigten ihre Macht durch strategische Heiraten und territoriale Expansion, was ihnen die Kontrolle über weite Teile Europas verschaffte. Unter Kaiser [[Karl]] V. wurde die Habsburgermonarchie zu einem der größten Reiche der Welt, das sowohl über Spanien, die Niederlande, Österreich und weite Teile des Heiligen Römischen Reiches als auch über Kolonien in der Neuen Welt herrschte"}, {"kategorie": "", "text": "Nach der Teilung der Habsburgermonarchie in eine spanische und eine österreichische Linie konzentrierte sich die Macht der österreichischen Habsburger auf Mittel- und Osteuropa. Die [[Türkenkriege]] und der [[Dreißigjährige]] Krieg formten diese Zeit stark. Unter Kaiserin [[Maria]] Theresia und ihrem Sohn [[Joseph]] II. erfolgten umfassende Reformen, um den Staat zu modernisieren und zu zentralisieren"}, {"kategorie": "", "text": "Nach den [[Napoleonischen]] Kriegen wurde die Habsburgermonarchie zur treibenden Kraft des [[Deutschen]] Bundes. Nach dem Verlust der Vormachtstellung in Deutschland 1866 wurde Österreich-Ungarn durch den [[Ausgleich]] von 1867 gegründet, wodurch die Monarchie in zwei Hälften geteilt wurde: die österreichische und die ungarische Reichshälfte"}, {"kategorie": "", "text": "Der [[Erste]] Weltkrieg führte 1918 zum Zerfall der Habsburgermonarchie. Die nationalen Spannungen zwischen den verschiedenen Völkern eskalierten, und nach der Niederlage Österreich-Ungarns wurde die Monarchie aufgelöst. Neue Nationalstaaten wie Österreich, Ungarn, die Tschechoslowakei, Jugoslawien und andere entstanden auf ihrem Territorium."}]'::jsonb, ''),
  ('habsbuagareich', 'Habsbuagareich', '', '', '', '', 'Habsburgerreich', '[{"kategorie": "allg.", "text": "\"die territorialen Besitzungen der Dynastie der Habsburger, die sich über mehrere Jahrhunderte erstreckten und weite Teile Europas umfassten\""}, {"kategorie": "", "text": "Dazu gehörten Gebiete wie das [[Heilige]] Römische Reich, Österreich, Ungarn, Böhmen, Teile Italiens, die Niederlande und Spanien"}, {"kategorie": "", "text": "Das Habsburgerreich bestand aus einer Vielzahl von Völkern und Kulturen, was es zu einem Vielvölkerstaat machte"}, {"kategorie": "", "text": "Besonders prägend waren die Habsburger durch ihre lange Herrschaft über Mitteleuropa, die bis zum Ende des [[Ersten]] Weltkriegs 1918 andauerte, als das Reich zerfiel"}]'::jsonb, ''),
  ('dopplmonachii', 'Dopplmonachii', '', '', '', '', 'Doppelmonarchie', '[{"kategorie": "", "text": "Sie entstand durch den [[Ausgleich]] von 1867, der die [[Habsburgermonarchie]] in zwei weitgehend autonome Teile aufteilte: das [[Kaiserreich]] Österreich und das [[Königreich]] Ungarn"}, {"kategorie": "", "text": "Beide Teile hatten eigene Parlamente und Regierungen, während sie durch den gemeinsamen Monarchen [[Franz]] Joseph I., der sowohl Kaiser von Österreich als auch König von Ungarn war, sowie gemeinsame Außenpolitik, Militär und Finanzen verbunden waren"}, {"kategorie": "", "text": "Die Doppelmonarchie endete 1918 nach dem [[Ersten]] Weltkrieg."}]'::jsonb, ''),
  ('mettanichgossn', 'Mettanichgossn', '', '', '', '', 'Metternichgasse', '[{"kategorie": "allg.", "text": "\"ruhige Wohnstraße im 3. Wiener Gemeindebezirk ([[Landstraße]])\""}, {"kategorie": "", "text": "Sie wurde nach dem österreichischen Staatsmann Fürst Klemens Wenzel von [[Metternich]] (1773–1859) benannt, einem der bedeutendsten Diplomaten des 19. Jahrhunderts"}, {"kategorie": "", "text": "Metternich war führend beim [[Wiener]] Kongress 1814–1815 und prägte die europäische Politik seiner Zeit maßgeblich"}, {"kategorie": "", "text": "Die Metternichgasse verläuft auf dem Grund des ehemaligen Metternichschen Gartens, bildet im sogenannten [[Diplomatenviertel]] eine wichtige Querachse (Verbindung der Strohgasse mit dem [[Rennweg]]) und besitzt eine weitgehend einheitliche Verbauung aus dem vierten Viertel des 19. Jahrhunderts (Wohnpalais und palaisartige Miethäuser)"}]'::jsonb, ''),
  ('canovagossn', 'Canovagossn', '', '', '', '', 'Canovagasse', '[{"kategorie": "allg.", "text": "\"kleine Straße im 1. Wiener Gemeindebezirk ([[Innere]] Stadt)\""}, {"kategorie": "", "text": "Sie wurde nach dem berühmten italienischen Bildhauer Antonio Canova (1757–1822) benannt, der als einer der größten Vertreter des [[Klassizismus]] gilt"}, {"kategorie": "", "text": "Canova war für seine meisterhaften Skulpturen, insbesondere von mythologischen Figuren, bekannt. Die Gasse liegt in der Nähe der [[Wiener]] Staatsoper und des [[Wiener]] Musikvereins und gehört zu einer gehobenen Gegend, die von historischen Gebäuden und kulturellen Einrichtungen geprägt ist."}]'::jsonb, ''),
  ('alliiirte', 'Alliiirte', '', '', '', '', 'Alliierte', '[{"kategorie": "allg.", "text": "\"jene verbündeten Staaten, die während des [[Zweiten]] Weltkriegs (1939–1945) gegen die [[Achsenmächte]] (Deutschland, Italien, Japan) kämpften\""}, {"kategorie": "", "text": "Die wichtigsten Alliierten waren die USA, die Sowjetunion, Großbritannien und Frankreich. Diese Staaten schlossen sich nach den deutschen Angriffen und dem Expansionsdrang der Achsenmächte zusammen, um deren Dominanz zu stoppen"}, {"kategorie": "", "text": "Nach dem Krieg teilten die Alliierten Deutschland und Österreich in [[Besatzungszonen]] auf und spielten eine entscheidende Rolle bei der Neuordnung Europas und dem Wiederaufbau."}]'::jsonb, ''),
  ('achsnmaechte', 'Achsnmächte', '', '', '', '', 'Achsenmächte', '[{"kategorie": "allg.", "text": "\"Bündnis von Deutschland, Italien und Japan während des [[Zweiten]] Weltkriegs\""}, {"kategorie": "", "text": "Diese drei Länder schlossen 1936 bzw. 1940 den sogenannten [[Dreimächtepakt]], der auf politischer und militärischer Zusammenarbeit basierte, um ihre Expansion und Kontrolle über Europa, Asien und Nordafrika durchzusetzen"}, {"kategorie": "", "text": "Deutschland unter Adolf Hitler, Italien unter Benito Mussolini und Japan unter Kaiser Hirohito strebten imperialistische Ziele an"}, {"kategorie": "", "text": "Österreich war während des [[Zweiten]] Weltkriegs als Teil des [[Deutschen]] Reiches in die Kriegsführung der Achsenmächte involviert. Nach dem [[Anschluss]] 1938 wurde Österreich in das [[Dritte]] Reich eingegliedert und war somit vollständig in die nationalsozialistische Kriegsmaschinerie integriert"}, {"kategorie": "", "text": "Viele Österreicher kämpften in der deutschen Wehrmacht, und das Land stellte Truppen und Ressourcen für den Krieg bereit. Die Niederlage der Achsenmächte gegen die Alliierten 1945 führte zum Ende des Kriegs und zu deren Zerfall"}, {"kategorie": "", "text": "Nach dem Krieg wurde Österreich als erstes Opfer der nationalsozialistischen Aggression dargestellt, was zur Wiederherstellung seiner Unabhängigkeit 1955 beitrug"}]'::jsonb, ''),
  ('holocaust', 'Holocaust', '', '', '', '', 'Holocaust', '[{"kategorie": "allg.", "text": "\"systematischer Völkermord an etwa sechs Millionen Juden durch das nationalsozialistische Regime unter Adolf Hitler während des [[Zweiten]] Weltkriegs\""}, {"kategorie": "", "text": "Zwischen 1941 und 1945 wurden Juden in Konzentrationslagern, Vernichtungslagern sowie durch Massakersysteme in ganz Europa ermordet"}, {"kategorie": "", "text": "Der Holocaust war Teil einer umfassenden rassistischen und antisemitischen Ideologie der Nationalsozialisten, die auch andere Gruppen wie Sinti und Roma, Homosexuelle, politische Gegner und Menschen mit Behinderungen verfolgte und ermordete"}, {"kategorie": "", "text": "Der Holocaust gilt als eines der dunkelsten Kapitel der Menschheitsgeschichte."}]'::jsonb, ''),
  ('nationalrood', 'Nationalrood', '', '', '', '', 'Nationalrat', '[{"kategorie": "pol.", "text": "\"erste Kammer des österreichischen Parlaments und das wichtigste gesetzgebende Organ des Landes\""}, {"kategorie": "", "text": "Der Nationalrat besteht aus 183 Abgeordneten, die alle fünf Jahre in einer allgemeinen, direkten Wahl bestimmt werden"}, {"kategorie": "", "text": "Der Nationalrat beschließt Gesetze, überwacht die Regierung und genehmigt das Budget"}, {"kategorie": "", "text": "Er vertritt das Volk und arbeitet eng mit dem [[Bundesrat]], der zweiten Kammer des Parlaments, zusammen"}, {"kategorie": "", "text": "Der Nationalrat ist zentraler Bestandteil der österreichischen Demokratie und hat eine bedeutende Rolle in der Gesetzgebung und Kontrolle der Exekutive."}]'::jsonb, ''),
  ('bundesrood', 'Bundesrood', '', '', '', '', 'Bundesrat', '[{"kategorie": "pol.", "text": "\"zweite Kammer des österreichischen Parlaments, welche die Interessen der Bundesländer auf nationaler Ebene vertritt\""}, {"kategorie": "", "text": "Der Bundesrat besteht aus 61 Mitgliedern, die von den [[Landtagen]] der neun Bundesländer entsandt werden"}, {"kategorie": "", "text": "Die Anzahl der Vertreter eines Bundeslands richtet sich nach der Bevölkerungsgröße"}, {"kategorie": "", "text": "Der Bundesrat hat die Aufgabe, Gesetze zu überprüfen, die der Nationalrat beschlossen hat, und kann Einspruch erheben"}, {"kategorie": "", "text": "Der Bundesrat kann jedoch keine eigenen Gesetze initiieren, und sein Veto kann in den meisten Fällen vom [[Nationalrat]] überstimmt werden."}]'::jsonb, ''),
  ('laundtoog', 'Laundtoog', '', '', '', '', 'Landtag', '[{"kategorie": "pol.", "text": "\"gesetzgebendes Organ in jedem der neun österreichischen Bundesländer, das aus gewählten Abgeordneten besteht, welche die Bürger des jeweiligen Bundeslandes vertreten\""}, {"kategorie": "", "text": "Der Landtag verabschiedet Landesgesetze, kontrolliert die Landesregierung und entscheidet über das Landesbudget"}, {"kategorie": "", "text": "Jedes der neun österreichischen Bundesländer hat einen eigenen Landtag, dessen Zusammensetzung durch Landtagswahlen bestimmt wird"}, {"kategorie": "", "text": "Die Aufgaben des Landtags sind in den Landesverfassungen festgelegt, und er spielt eine zentrale Rolle in der föderalen Struktur Österreichs"}]'::jsonb, ''),
  ('bundeslaund', 'Bundeslaund', '', '', '', '', 'Bundesland', '[{"kategorie": "pol.", "text": "\"eigenständige Verwaltungseinheit innerhalb der föderalen Struktur des Landes\""}, {"kategorie": "", "text": "Österreich besteht aus neun Bundesländern: Wien, Niederösterreich, Oberösterreich, Burgenland, Steiermark, Kärnten, Salzburg, Tirol und Vorarlberg"}, {"kategorie": "", "text": "Jedes Bundesland hat eine eigene Landesverfassung, einen [[Landtag]] (Parlament) und eine [[Landesregierung]]"}, {"kategorie": "", "text": "Die Bundesländer haben eigene Zuständigkeiten, etwa in Bereichen wie Bildung, Bauwesen und Gesundheitswesen"}, {"kategorie": "", "text": "Die Bundesländer wirken darüber hinaus im [[Bundesrat]], der zweiten Kammer des österreichischen Parlaments, an der Bundesgesetzgebung mit."}]'::jsonb, ''),
  ('laundesregiirung', 'Laundesregiirung', '', '', '', '', 'Landesregierung', '[{"kategorie": "pol.", "text": "\"das Exekutivorgan in jedem der neun österreichischen Bundesländer\""}, {"kategorie": "", "text": "Sie besteht aus dem [[Landeshauptmann]] (oder der Landeshauptfrau) sowie mehreren [[Landesräten]], wobei Wien diesbezüglich eine Sonderstellung hat"}, {"kategorie": "", "text": "Sie setzt die im Landtag beschlossenen Gesetze um, verwaltet die Landesangelegenheiten und ist für die Ausführung der Landesverfassung verantwortlich"}, {"kategorie": "", "text": "Der Landeshauptmann ist zugleich der Vorsitzende der Landesregierung und repräsentiert das Bundesland nach außen"}, {"kategorie": "", "text": "Die Aufgabenbereiche der Landesregierung umfassen Themen wie Bildung, Bauwesen, Gesundheitswesen und andere regionale Zuständigkeiten."}]'::jsonb, ''),
  ('laundeshauptmaunn', 'Laundeshauptmaunn', '', '', '', '', 'Landeshauptmann', '[{"kategorie": "pol.", "text": "\"Oberhaupt einer [[Landesregierung]] und damit der höchste politische Repräsentant eines Bundeslandes\""}, {"kategorie": "", "text": "Er ist sowohl [[Regierungschef]] des jeweiligen [[Bundeslandes]] als auch Vorsitzender des [[Landtages]]. Zu den Hauptaufgaben des Landeshauptmanns gehört es, die [[Landesregierung]] zu leiten, die Verwaltung des Bundeslandes zu organisieren und Gesetze, die im Landtag beschlossen werden, umzusetzen"}, {"kategorie": "", "text": "Eine Besonderheit in Österreich stellt die [[Stadt]] Wien dar, da sie sowohl Bundesland als auch Gemeinde ist. Der Wiener Landeshauptmann ist gleichzeitig der [[Bürgermeister]] der Stadt Wien. Diese Doppelfunktion macht das Amt in Wien einzigartig im Vergleich zu den anderen Bundesländern, wo Landeshauptmann und Bürgermeister getrennte Ämter sind"}, {"kategorie": "", "text": "Der [[Wiener]] Landeshauptmann/Bürgermeister hat folgende zentrale Aufgaben: (i) Leitung der [[Landesregierung]] (er führt den Vorsitz in der Wiener Landesregierung und ist für die Ausführung der Landesgesetze verantwortlich), (ii) Verwaltung der Stadt Wien (als Bürgermeister ist er auch für die kommunale Verwaltung der Stadt verantwortlich, was von der Stadtplanung bis hin zur öffentlichen Sicherheit reicht), (iii) Repräsentative Aufgaben (der Landeshauptmann/Bürgermeister vertritt sowohl das Bundesland Wien als auch die Stadt Wien nach außen), (iv) Der amtierende Landeshauptmann von Wien wird vom [[Wiener]] Landtag gewählt, der gleichzeitig auch [[Gemeinderat]] der Stadt Wien ist, und ernennt die weiteren Mitglieder der [[Wiener]] Landesregierung, die gleichzeitig den [[Stadtsenat]] bilden"}, {"kategorie": "", "text": "Diese Kombination aus Bundesland und Stadt verleiht dem Amt des Wiener Landeshauptmanns besondere Bedeutung in der politischen Landschaft Österreichs."}]'::jsonb, ''),
  ('laundeshauptfrau', 'Laundeshauptfrau', '', '', '', '', 'Landeshauptfrau', '[{"kategorie": "pol.", "text": "\"Oberhaupt einer [[Landesregierung]] und damit der höchste politische Repräsentant eines Bundeslandes\""}, {"kategorie": "", "text": "Sie ist sowohl [[Regierungschefin]] des jeweiligen [[Bundeslandes]] als auch Vorsitzende des [[Landtages]]. Zu den Hauptaufgaben der Landeshauptfrau gehört es, die [[Landesregierung]] zu leiten, die Verwaltung des Bundeslandes zu organisieren und Gesetze, die im Landtag beschlossen werden, umzusetzen"}, {"kategorie": "", "text": "Eine Besonderheit in Österreich stellt die [[Stadt]] Wien dar, da sie sowohl Bundesland als auch Gemeinde ist. Der Wiener Landeshauptmann/Landeshauptfrau ist gleichzeitig der [[Bürgermeister]]/in der Stadt Wien. Diese Doppelfunktion macht das Amt in Wien einzigartig im Vergleich zu den anderen Bundesländern, wo Landeshauptmann und Bürgermeister getrennte Ämter sind"}, {"kategorie": "", "text": "Der [[Wiener]] Landeshauptmann/Bürgermeister (Landeshauptfrau/Bürgermeisterin) hat folgende zentrale Aufgaben: (i) Leitung der [[Landesregierung]] (er/sie führt den Vorsitz in der Wiener Landesregierung und ist für die Ausführung der Landesgesetze verantwortlich), (ii) Verwaltung der Stadt Wien (als Bürgermeister/in ist er/sie auch für die kommunale Verwaltung der Stadt verantwortlich, was von der Stadtplanung bis hin zur öffentlichen Sicherheit reicht), (iii) Repräsentative Aufgaben (der Landeshauptmann/Bürgermeister [Landeshauptfrau/Bürgermeisterin] vertritt sowohl das Bundesland Wien als auch die Stadt Wien nach außen), (iv) Der amtierende Landeshauptmann (Landeshauptfrau)  von Wien wird vom [[Wiener]] Landtag gewählt, der gleichzeitig auch [[Gemeinderat]] der Stadt Wien ist, und ernennt die weiteren Mitglieder der [[Wiener]] Landesregierung, die gleichzeitig den [[Stadtsenat]] bilden"}, {"kategorie": "", "text": "Diese Kombination aus Bundesland und Stadt verleiht dem Amt des Wiener Landeshauptmanns (der Wiener Landeshauptfrau) besondere Bedeutung in der politischen Landschaft Österreichs."}]'::jsonb, ''),
  ('laundesrood', 'Laundesrood', '', '', '', '', 'Landesrat', '[{"kategorie": "pol.", "text": "\"Mitglied der Landesregierung, welches für spezifische Ressorts und Aufgabenbereiche auf Landesebene zuständig ist, ähnlich wie ein [[Minister]] auf Bundesebene\""}, {"kategorie": "", "text": "Jeder Landesrat leitet ein bestimmtes Ressort, wie z. B. Gesundheit, Bildung oder Verkehr, und ist für die Umsetzung der Landespolitik in diesem Bereich verantwortlich. Der Landesrat wird vom [[Landtag]] gewählt und arbeitet eng mit dem [[Landeshauptmann]] sowie den anderen Mitgliedern der [[Landesregierung]] zusammen"}, {"kategorie": "", "text": "In Wien gibt es eine Besonderheit: Da Wien sowohl Bundesland als auch Stadt ist, nehmen die [[Stadträte]] im [[Stadtsenat]] auch die Funktion von Landesräten in der Landesregierung wahr. Diese Doppelrolle als Stadtrat und Landesrat bedeutet, dass sie gleichzeitig für städtische und landespolitische Angelegenheiten zuständig sind"}, {"kategorie": "", "text": "Die Wiener Landesräte (Stadträte) haben daher folgende Hauptaufgaben: (i) Verantwortung für spezifische Ressorts (jeder Stadtrat/Landesrat ist für ein bestimmtes Ressort zuständig, wie z. B. Wohnbau, Finanzen oder Verkehr), (ii) Umsetzung von Landes- und Stadtgesetzen (sie sorgen dafür, dass die Gesetze und politischen Vorgaben in ihrem Verantwortungsbereich sowohl auf städtischer als auch auf Landesebene eingehalten und umgesetzt werden), (iii) Zusammenarbeit im Stadtsenat/Landesregierung (sie arbeiten unter der Leitung des Wiener [[Landeshauptmanns]]/[[Bürgermeisters]] und sind Teil der kollektiven Entscheidungsfindung in der [[Stadtregierung]])"}, {"kategorie": "", "text": "Durch diese Doppelfunktion haben die Wiener Stadträte/Landesräte eine besondere Bedeutung, da sie nicht nur städtische Verwaltungsaufgaben wahrnehmen, sondern auch an der Führung des Bundeslandes Wien beteiligt sind"}]'::jsonb, ''),
  ('regiirungsschef', 'Regiirungsschef', '', '', '', '', 'Regierungschef', '[{"kategorie": "pol.", "text": "\"Leiter der [[Bundesregierung]], d.h. der [[Bundeskanzler]], der die [[Exekutive]] auf Bundesebene anführt und somit die wichtigste politische Figur in der Regierung darstellt\""}, {"kategorie": "", "text": "Der Bundeskanzler ist für die Koordination der Regierungsarbeit verantwortlich und steht dem [[Ministerrat]], also den Sitzungen der Bundesregierung, vor. Er vertritt die Regierung nach außen und spielt eine Schlüsselrolle in der Entwicklung und Umsetzung der nationalen Politik"}, {"kategorie": "", "text": "Aufgaben des Bundeskanzlers (Regierungschefs): (i) Leitung der Bundesregierung (der Bundeskanzler koordiniert die Aktivitäten der [[Bundesminister]] und sorgt dafür, dass die Regierungspolitik einheitlich umgesetzt wird), (ii) Politische Führung (er setzt politische Schwerpunkte und vertritt die Regierung in öffentlichen und internationalen Angelegenheiten), (iii) Zusammenarbeit mit dem [[Bundespräsidenten]] (obwohl der Bundespräsident formell das Staatsoberhaupt ist, arbeitet der Bundeskanzler eng mit ihm zusammen, insbesondere bei der Ernennung und Entlassung von Regierungsmitgliedern)"}, {"kategorie": "", "text": "Der Bundeskanzler wird in Österreich nicht direkt vom Volk gewählt, sondern von der Mehrheit im [[Nationalrat]] (dem Parlament) bestimmt. Der Bundespräsident ernennt daraufhin den Bundeskanzler und die Bundesregierung"}, {"kategorie": "", "text": "In den Bundesländern ist der entsprechende Regierungschef der [[Landeshauptmann]] (oder [[Landeshauptfrau]]), der die Landesregierung leitet und ähnliche Aufgaben auf regionaler Ebene wahrnimmt."}]'::jsonb, ''),
  ('minista', 'Minista', '', '', '', '', 'Minister', '[{"kategorie": "pol.", "text": "\"Mitglied der Bundesregierung, der ein spezifisches Ressort oder Ministerium leitet\""}, {"kategorie": "", "text": "Jeder Minister ist für ein bestimmtes Politikfeld zuständig, wie beispielsweise Finanzen, Inneres, Bildung oder Gesundheit"}, {"kategorie": "", "text": "Die Minister sind verantwortlich für die Umsetzung der Regierungspolitik in ihren Bereichen und arbeiten eng mit dem [[Bundeskanzler]] und den anderen Ministern zusammen, um die Gesamtpolitik der Regierung zu koordinieren und umzusetzen"}, {"kategorie": "", "text": "Die Minister werden vom [[Bundespräsidenten]] auf Vorschlag des Bundeskanzlers ernannt. Sie sind gegenüber dem [[Nationalrat]] verantwortlich, der das Recht hat, einzelnen Ministern das Vertrauen zu entziehen, was zur Absetzung des Ministers führen kann"}, {"kategorie": "", "text": "Auf der Ebene der [[Bundesländer]] gibt es keine Minister, sondern [[Landesräte]], die ähnliche Aufgaben in den [[Landesregierungen]] übernehmen, wobei der [[Landeshauptmann]] als Regierungschef fungiert."}]'::jsonb, ''),
  ('bundesminista', 'Bundesminista', '', '', '', '', 'Bundesminister', '[{"kategorie": "pol.", "text": "\"Mitglied der Bundesregierung, der ein spezifisches Ressort oder Ministerium leitet\""}, {"kategorie": "", "text": "Jeder Minister ist für ein bestimmtes Politikfeld zuständig, wie beispielsweise Finanzen, Inneres, Bildung oder Gesundheit"}, {"kategorie": "", "text": "Die Minister sind verantwortlich für die Umsetzung der Regierungspolitik in ihren Bereichen und arbeiten eng mit dem [[Bundeskanzler]] und den anderen Ministern zusammen, um die Gesamtpolitik der Regierung zu koordinieren und umzusetzen"}, {"kategorie": "", "text": "Die Minister werden vom [[Bundespräsidenten]] auf Vorschlag des Bundeskanzlers ernannt. Sie sind gegenüber dem [[Nationalrat]] verantwortlich, der das Recht hat, einzelnen Ministern das Vertrauen zu entziehen, was zur Absetzung des Ministers führen kann"}, {"kategorie": "", "text": "Auf der Ebene der [[Bundesländer]] gibt es keine Minister, sondern [[Landesräte]], die ähnliche Aufgaben in den [[Landesregierungen]] übernehmen, wobei der [[Landeshauptmann]] als Regierungschef fungiert."}]'::jsonb, ''),
  ('bundeskaunzla', 'Bundeskaunzla', '', '', '', '', 'Bundeskanzler', '[{"kategorie": "pol.", "text": "\"Regierungschef Österreichs, der die [[Bundesregierung]] leitet\""}, {"kategorie": "", "text": "Er ist die wichtigste politische Figur in der [[Exekutive]] auf Bundesebene und spielt eine zentrale Rolle bei der Ausgestaltung und Umsetzung der politischen Agenda des Landes"}, {"kategorie": "", "text": "Der Bundeskanzler koordiniert die Arbeit der Ministerien und ist für die allgemeine Leitung der Regierung verantwortlich"}, {"kategorie": "", "text": "Der Bundeskanzler steht an der Spitze der Bundesregierung und leitet die [[Ministerratssitzungen]], bei denen die wichtigsten politischen Entscheidungen und Gesetzesvorlagen besprochen und beschlossen werden"}, {"kategorie": "", "text": "Er koordiniert die Arbeit der verschiedenen Ministerien, um sicherzustellen, dass die Regierungsmaßnahmen kohärent und abgestimmt durchgeführt werden"}, {"kategorie": "", "text": "Der Bundeskanzler vertritt die österreichische Bundesregierung nach außen, sowohl auf nationaler als auch auf internationaler Ebene"}, {"kategorie": "", "text": "Der Bundeskanzler schlägt dem [[Bundespräsidenten]] die [[Minister]] vor, die dieser dann offiziell ernennt. Außerdem kann er politische Vorschläge einbringen, die in der [[Regierung]] diskutiert werden"}, {"kategorie": "", "text": "Der Bundeskanzler wird nicht direkt vom Volk gewählt, sondern vom [[Bundespräsidenten]] auf Basis der Mehrheitsverhältnisse im [[Nationalrat]] ernannt. In der Regel ist er der Vorsitzende der stärksten Partei oder Koalition im Nationalrat. Der Bundeskanzler ist dem Nationalrat gegenüber politisch verantwortlich, der das Recht hat, ihm durch ein [[Misstrauensvotum]] das Vertrauen zu entziehen."}]'::jsonb, ''),
  ('vizekaunzla', 'Vizekaunzla', '', '', '', '', 'Vizekanzler', '[{"kategorie": "pol.", "text": "\"stellvertretender [[Regierungschef]] und zweithöchster Amtsträger in der [[Bundesregierung]]\""}, {"kategorie": "", "text": "Er unterstützt den [[Bundeskanzler]] bei der Leitung der [[Regierung]] und übernimmt dessen Aufgaben, wenn der Bundeskanzler verhindert ist oder ausfällt"}, {"kategorie": "", "text": "Der Vizekanzler ist in der Regel auch Leiter eines [[Ministeriums]] und hat somit eigene Ressortaufgaben, zusätzlich zu seinen Stellvertreterfunktionen"}, {"kategorie": "", "text": "Der Vizekanzler wird, wie der Bundeskanzler, vom [[Bundespräsidenten]] ernannt, auf Vorschlag des Bundeskanzlers"}, {"kategorie": "", "text": "In der Praxis ist der Vizekanzler oft der Vorsitzende oder ein hochrangiges Mitglied der zweitstärksten Partei in einer Koalition. Diese Position ist besonders in Koalitionsregierungen wichtig, da der Vizekanzler in vielen Fällen die Interessen des Koalitionspartners vertritt und dafür sorgt, dass die Politik der Regierung von beiden Parteien gemeinsam getragen wird."}]'::jsonb, ''),
  ('koalitionsregiirung', 'Koalitionsregiirung', '', '', '', '', 'Koalitionsregierung', '[{"kategorie": "pol.", "text": "\"Regierungsform, bei der zwei oder mehr politische Parteien zusammenarbeiten, um eine gemeinsame Regierung zu bilden\""}, {"kategorie": "", "text": "Dies ist notwendig, wenn keine einzelne Partei nach einer Wahl die absolute Mehrheit im [[Nationalrat]] (dem Parlament) hat und somit nicht allein regieren kann"}, {"kategorie": "", "text": "In einer Koalitionsregierung teilen sich die Parteien die Regierungsämter, und ihre Vertreter (Minister) arbeiten gemeinsam an der Umsetzung eines koordinierten Regierungsprogramms"}, {"kategorie": "", "text": "In Österreich sind Koalitionsregierungen sehr häufig, da das politische System auf Verhältnismäßigkeit basiert und selten eine Partei allein die Mehrheit der Sitze im Nationalrat erreicht."}]'::jsonb, ''),
  ('misstrauensvotum', 'Misstrauensvotum', '', '', '', '', 'Misstrauensvotum', '[{"kategorie": "pol.", "text": "\"parlamentarisches Instrument, mit dem der [[Nationalrat]] das Vertrauen in die [[Bundesregierung]] oder in einzelne Mitglieder der [[Regierung]] (z. B. den [[Bundeskanzler]] oder einen [[Minister]]) entziehen kann\""}, {"kategorie": "", "text": "Es ist ein wesentliches Mittel der parlamentarischen Kontrolle über die [[Exekutive]] und dient dazu, die Regierung zur Rechenschaft zu ziehen und notfalls zu stürzen, wenn das [[Parlament]] die Regierungsarbeit nicht mehr unterstützt"}, {"kategorie": "", "text": "Ein Misstrauensantrag kann von den [[Abgeordneten]] des [[Nationalrats]] eingebracht werden. Über den Antrag wird im [[Nationalrat]] abgestimmt"}, {"kategorie": "", "text": "Wird das Misstrauensvotum angenommen, muss die betroffene Regierung oder das betreffende Regierungsmitglied zurücktreten. Bei einem erfolgreichen Votum gegen die gesamte Bundesregierung muss der [[Bundespräsident]] eine neue Regierung ernennen"}, {"kategorie": "", "text": "Das Misstrauensvotum dient als Kontrollmechanismus, um sicherzustellen, dass die Bundesregierung das Vertrauen des Parlaments behält. Es stärkt das parlamentarische System und sorgt dafür, dass die Regierung in Übereinstimmung mit den Mehrheiten im Nationalrat handelt"}, {"kategorie": "", "text": "In der Praxis ist ein erfolgreiches Misstrauensvotum in Österreich selten, da es in der Regel von der Opposition beantragt wird und die Regierungsparteien im Nationalrat eine Mehrheit haben. Ein bemerkenswertes Beispiel fand jedoch 2019 statt, als der Nationalrat der Regierung von Sebastian Kurz das Vertrauen entzog, was zur Entlassung der gesamten Bundesregierung führte."}]'::jsonb, ''),
  ('ministerium', 'Ministerium', '', '', '', '', 'Ministerium', '[{"kategorie": "pol.", "text": "\"zentrale staatliche Behörde, die von einem [[Minister]] geleitet wird und für spezifische Politikbereiche zuständig ist\""}, {"kategorie": "", "text": "Jedes Ministerium hat die Aufgabe, Gesetze in seinem Bereich zu vollziehen und die Regierungsentscheidungen umzusetzen"}, {"kategorie": "", "text": "Es handelt sich um eine Organisationseinheit innerhalb der [[Exekutive]], die für die Verwaltung und politische Führung des jeweiligen Ressorts verantwortlich ist, wie z. B. Finanzen, Inneres, Bildung oder Gesundheit"}, {"kategorie": "", "text": "Jedes Ministerium ist ein wesentliches Instrument zur Umsetzung der politischen und administrativen Aufgaben der [[Regierung]]. Sie koordinieren große Teile der öffentlichen Verwaltung und sind für die Bereitstellung grundlegender öffentlicher Dienstleistungen zuständig."}]'::jsonb, ''),
  ('bundesministerium', 'Bundesministerium', '', '', '', '', 'Bundesministerium', '[{"kategorie": "pol.", "text": "\"zentrale staatliche Behörde, die von einem [[Bundesminister]] geleitet wird und für spezifische Politikbereiche zuständig ist\""}, {"kategorie": "", "text": "Jedes Bundesministerium hat die Aufgabe, Gesetze in seinem Bereich zu vollziehen und die Regierungsentscheidungen umzusetzen"}, {"kategorie": "", "text": "Es handelt sich um eine Organisationseinheit innerhalb der [[Exekutive]], die für die Verwaltung und politische Führung des jeweiligen Ressorts verantwortlich ist, wie z. B. Finanzen, Inneres, Bildung oder Gesundheit"}, {"kategorie": "", "text": "Jedes Bundesministerium ist ein wesentliches Instrument zur Umsetzung der politischen und administrativen Aufgaben der [[Regierung]]. Sie koordinieren große Teile der öffentlichen Verwaltung und sind für die Bereitstellung grundlegender öffentlicher Dienstleistungen zuständig."}]'::jsonb, ''),
  ('regiirung', 'Regiirung', '', '', '', '', 'Regierung', '[{"kategorie": "pol.", "text": "\"zentrales Exekutivorgan auf Bundesebene, verantwortlich für die Führung der Staatsgeschäfte und die Umsetzung der Gesetze, die vom [[Parlament]] beschlossen werden\""}, {"kategorie": "", "text": "Sie besteht aus dem [[Bundeskanzler]], dem [[Vizekanzler]] und den [[Bundesministern]], die jeweils bestimmte Ressorts leiten, sowie den [[Staatssekretären]], welche den [[Bundesministern]] unterstellt sind und diese bei der Erfüllung deren Aufgaben unterstützen"}, {"kategorie": "", "text": "Die Bundesregierung vertritt die politische Leitung und koordiniert die Verwaltung des Staates"}, {"kategorie": "", "text": "Die Regierung wird formell vom [[Bundespräsidenten]] ernannt"}, {"kategorie": "", "text": "Der Bundeskanzler wird in der Regel von der stärksten Partei im [[Nationalrat]] gestellt, und die [[Minister]] werden auf Vorschlag des Kanzlers vom Bundespräsidenten bestellt"}, {"kategorie": "", "text": "Die Regierung ist dem Nationalrat gegenüber verantwortlich, und der Nationalrat kann der Regierung durch ein [[Misstrauensvotum]] das Vertrauen entziehen"}, {"kategorie": "", "text": "In Österreich sind [[Koalitionsregierungen]] aufgrund des proportionalen Wahlsystems häufig, da selten eine einzelne Partei die Mehrheit der Sitze im Nationalrat erreicht. Daher arbeitet die Bundesregierung oft als Koalition aus zwei oder mehr Parteien, die sich auf ein gemeinsames Regierungsprogramm einigen."}]'::jsonb, ''),
  ('ministarood', 'Ministarood', '', '', '', '', 'Ministerrat', '[{"kategorie": "pol.", "text": "\"Versammlung der [[Bundesregierung]], welche eine zentrale Rolle in der Führung und Koordination der [[Exekutive]] spielt\""}, {"kategorie": "", "text": "Im Ministerrat kommen der [[Bundeskanzler]], der [[Vizekanzler]] und alle [[Bundesminister]] zusammen, um über wichtige politische Entscheidungen und Gesetzesvorlagen zu beraten und diese zu beschließen"}, {"kategorie": "", "text": "Der Bundeskanzler leitet die Sitzungen des Ministerrats, in denen die Minister ihre Vorschläge einbringen und gemeinsam darüber beraten"}, {"kategorie": "", "text": "Die Sitzungen finden regelmäßig statt, meist wöchentlich, und sind nicht öffentlich"}, {"kategorie": "", "text": "Beschlüsse werden im Konsens gefasst, was bedeutet, dass die Mitglieder der Regierung gemeinsam entscheiden und keine formellen Abstimmungen wie in Parlamentssitzungen stattfinden."}]'::jsonb, ''),
  ('ministaroodssitzungan', 'Ministaroodssitzungan', '', '', '', '', 'Ministerratssitzungen', '[{"kategorie": "pol.", "text": "\"regelmäßige Treffen der [[Bundesregierung]], bei denen der [[Bundeskanzler]], der [[Vizekanzler]] und alle [[Bundesminister]] zusammenkommen, um politische Entscheidungen zu diskutieren und zu beschließen\""}, {"kategorie": "", "text": "Diese Sitzungen sind ein zentrales Element der Regierungsarbeit und dienen der Koordination und Festlegung der politischen Agenda sowie der Verwaltung des Staates"}, {"kategorie": "", "text": "Der Bundeskanzler leitet die Sitzungen und stellt sicher, dass die Themen gemäß der Tagesordnung behandelt werden"}, {"kategorie": "", "text": "In den Ministerratssitzungen werden Gesetzesvorschläge und politische Maßnahmen besprochen. Diese werden anschließend entweder umgesetzt oder an das [[Parlament]] ([[Nationalrat]]) weitergeleitet, wo sie beschlossen werden müssen"}, {"kategorie": "", "text": "Der Ministerrat beschließt über [[Gesetzesvorlagen]], die von den einzelnen Ministerien eingebracht werden, und trifft auch Entscheidungen über Verordnungen, die direkt in Kraft treten können"}, {"kategorie": "", "text": "Die Ministerratssitzungen finden regelmäßig statt, meist wöchentlich. Sie sind nicht öffentlich, was Vertraulichkeit bei der Entscheidungsfindung gewährleistet. Im Anschluss an die Sitzungen werden jedoch die wichtigsten Beschlüsse öffentlich bekannt gegeben"}, {"kategorie": "", "text": "Die Ministerratssitzungen sind das Herzstück der exekutiven Arbeit auf Bundesebene. Hier werden wichtige politische Entscheidungen vorbereitet und strategische Weichenstellungen vorgenommen, die die Richtung der Regierungspolitik bestimmen. Das Ziel dieser Sitzungen ist es, eine einheitliche Linie der Regierung zu gewährleisten und unterschiedliche Ressorts aufeinander abzustimmen."}]'::jsonb, ''),
  ('gesetzesentwuaf', 'Gesetzesentwuaf', '', '', '', '', 'Gesetzesvorschlag', '[{"kategorie": "", "text": "Sie bildet den ersten Schritt im [[Gesetzgebungsverfahren]], das mit der Beratung und Abstimmung im [[Parlament]] beginnt und schließlich zur Umsetzung in der Praxis führen kann"}, {"kategorie": "", "text": "Eine Gesetzesvorlage kann von der Bundesregierung (als sogenannte [[Regierungsvorlage]]), von den [[Abgeordneten]] des Nationalrats (Initiativanträge), von Mitgliedern des [[Bundesrats]] oder durch [[Volksbegehren]] eingebracht werden"}, {"kategorie": "", "text": "Die Gesetzesvorlage wird im Nationalrat in drei [[Lesungen]] behandelt. In diesen Lesungen wird der Entwurf diskutiert, Änderungen vorgeschlagen und schließlich darüber abgestimmt"}, {"kategorie": "", "text": "Nach der Beratung und gegebenenfalls Änderungen erfolgt die Abstimmung im Nationalrat. Bei einer Mehrheit wird die Gesetzesvorlage angenommen"}, {"kategorie": "", "text": "Nach der Annahme im Nationalrat wird die Gesetzesvorlage dem Bundesrat zur Zustimmung übermittelt. In seltenen Fällen kann der Bundesrat ein Veto einlegen"}, {"kategorie": "", "text": "Abschließend muss das Gesetz vom [[Bundespräsidenten]] unterzeichnet werden, bevor es veröffentlicht und rechtskräftig wird"}, {"kategorie": "", "text": "In Österreich sind [[Regierungsvorlagen]] die häufigste Form von Gesetzesvorlagen, da die [[Bundesregierung]] oft die politische Initiative für gesetzliche Änderungen übernimmt​"}]'::jsonb, ''),
  ('ausschussberootung', 'Ausschussberootung', '', '', '', '', 'Ausschussberatung', '[{"kategorie": "pol.", "text": "\"entscheidende Phase, in der [[Gesetzesentwürfe]] im Detail geprüft und diskutiert werden, bevor sie zur endgültigen Abstimmung im [[Nationalrat]] kommen\""}, {"kategorie": "", "text": "[[Ausschüsse]] sind kleinere Gruppen von Abgeordneten, die in verschiedenen Fachbereichen spezialisiert sind, wie z. B. Finanzen, Gesundheit oder Bildung"}, {"kategorie": "", "text": "Diese Ausschüsse arbeiten die [[Gesetzesvorschläge]] durch, analysieren deren Auswirkungen und erarbeiten Berichte, die als Grundlage für die weiteren parlamentarischen Debatten dienen"}, {"kategorie": "", "text": "Jeder Gesetzesentwurf wird nach der ersten [[Lesung]] im [[Nationalrat]] an einen entsprechenden [[Fachausschuss]] überwiesen, der sich mit dem Themenbereich des Entwurfs beschäftigt. Diese Ausschüsse bestehen aus [[Abgeordneten]] des Nationalrats, die in dem jeweiligen Bereich Expertise haben"}, {"kategorie": "", "text": "Im Ausschuss wird der Gesetzesentwurf inhaltlich detailliert analysiert. Experten und Interessenvertreter können gehört werden, um zusätzliche Informationen und Perspektiven beizutragen. Abgeordnete können Änderungen (sogenannte Abänderungsanträge) einbringen, die im Ausschuss diskutiert und beschlossen werden"}, {"kategorie": "", "text": "Nach der Diskussion und Prüfung erstellt der Ausschuss einen Bericht, in dem er seine Empfehlungen an den Nationalrat formuliert. Dieser Bericht gibt an, ob der Entwurf unverändert angenommen, abgeändert oder abgelehnt werden sollte"}, {"kategorie": "", "text": "Die Ausschussberatung ist entscheidend für die inhaltliche und technische Ausarbeitung eines Gesetzes. Sie ermöglicht eine vertiefte Auseinandersetzung mit dem Entwurf, die in der großen Parlamentsdebatte oft nicht in dieser Detailtiefe möglich ist"}, {"kategorie": "", "text": "Ausschussberatungen können öffentlich oder nicht-öffentlich stattfinden. Bei besonders wichtigen Themen kann es auch öffentliche Anhörungen geben"}, {"kategorie": "", "text": "Nach Abschluss der Ausschussberatung wird der Entwurf in der zweiten [[Lesung]] im Nationalrat erneut diskutiert, bevor in der dritten Lesung eine endgültige Abstimmung über das Gesetz erfolgt."}]'::jsonb, ''),
  ('vafoansauntroog', 'Vafoansauntroog', '', '', '', '', 'Verfahrensantrag', '[{"kategorie": "pol.", "text": "\"Antrag im österreichischen Parlament, der darauf abzielt, den Ablauf und die Organisation einer parlamentarischen Sitzung zu beeinflussen oder anzupassen\""}, {"kategorie": "", "text": "Im Gegensatz zu inhaltlichen Anträgen, die sich auf [[Gesetze]] oder politische Themen beziehen, betreffen Verfahrensanträge ausschließlich den formal-organisatorischen Ablauf von Debatten und Abstimmungen im [[Parlament]]"}, {"kategorie": "", "text": "Verfahrensanträge zielen darauf ab, den Ablauf einer Sitzung zu ändern, zu unterbrechen oder zu steuern. Beispiele hierfür sind Anträge auf Vertagung, Schluss der Debatte, Änderung der Tagesordnung oder Durchführung einer namentlichen Abstimmung"}, {"kategorie": "", "text": "Über Verfahrensanträge wird in der Regel sofort abgestimmt, ohne dass sie in einem [[Fachausschuss]] beraten werden. Sie betreffen meist den unmittelbaren Verlauf der Sitzung, sodass eine schnelle Entscheidung notwendig ist"}, {"kategorie": "", "text": "Verfahrensanträge können von jedem [[Abgeordneten]] während einer Sitzung gestellt werden. Der [[Nationalratspräsident]] oder Sitzungsleiter entscheidet, ob und wie über den Antrag abgestimmt wird."}]'::jsonb, ''),
  ('untasuchungsausschuss', 'Untasuchungsausschuss', '', '', '', '', 'Untersuchungsausschuss', '[{"kategorie": "pol.", "text": "\"parlamentarisches Instrument, das dazu dient, bestimmte Sachverhalte oder mögliche Missstände in der Verwaltung oder Politik zu untersuchen\""}, {"kategorie": "", "text": "Ein Untersuchungsausschuss wird eingesetzt, um Transparenz zu schaffen und politische Verantwortung zu klären. Er ist ein wichtiges Mittel der parlamentarischen Kontrolle über die [[Regierung]] und andere staatliche Organe"}, {"kategorie": "", "text": "Ein Untersuchungsausschuss kann vom [[Nationalrat]] oder [[Bundesrat]] eingesetzt werden. In der Regel erfolgt dies auf Antrag einer bestimmten Anzahl von [[Abgeordneten]], um spezifische Vorfälle oder Themen zu prüfen, die von öffentlichem Interesse sind"}, {"kategorie": "", "text": "Der Untersuchungsausschuss hat die Aufgabe, einen bestimmten Sachverhalt aufzuklären. Dies kann Fehlverhalten in der Verwaltung, Korruption, Missbrauch staatlicher Mittel oder andere potenzielle Unregelmäßigkeiten betreffen"}, {"kategorie": "", "text": "Der Ausschuss hat weitreichende Ermittlungsbefugnisse. Er kann Zeugen vorladen, Beweismittel anfordern und auch Beamte oder Regierungsmitglieder befragen. Diese Befugnisse ähneln denen von Gerichten, was den Ausschuss zu einem starken Kontrollinstrument macht"}, {"kategorie": "", "text": "Nach Abschluss der Untersuchungen erstellt der Ausschuss einen Bericht, in dem die Ergebnisse zusammengefasst und gegebenenfalls Empfehlungen ausgesprochen werden. Dieser Bericht wird im [[Nationalrat]] diskutiert und kann zu weiteren politischen Konsequenzen führen"}, {"kategorie": "", "text": "Die Sitzungen eines Untersuchungsausschusses können öffentlich oder nicht-öffentlich sein. Bei besonders sensiblen Themen kann es jedoch Beschränkungen in der Öffentlichkeit der Verhandlungen geben."}]'::jsonb, ''),
  ('gesetzesauntroog', 'Gesetzesauntroog', '', '', '', '', 'Gesetzesantrag', '[{"kategorie": "pol.", "text": "\"formeller Vorschlag, ein neues [[Gesetz]] zu erlassen oder ein bestehendes Gesetz zu ändern\""}, {"kategorie": "", "text": "Dieser Antrag wird entweder von [[Abgeordneten]] des [[Nationalrats]], der [[Bundesregierung]] oder unter bestimmten Bedingungen auch durch [[Volksbegehren]] eingebracht"}, {"kategorie": "", "text": "Der Gesetzesantrag bildet den ersten Schritt im [[Gesetzgebungsprozess]] und durchläuft anschließend mehrere Phasen der Beratung, Prüfung und Abstimmung im Parlament"}, {"kategorie": "", "text": "Arten von Gesetzesanträgen: (i) [[Initiativantrag]] (dieser Antrag wird von einer Gruppe von mindestens fünf Abgeordneten des Nationalrats eingebracht. Er dient der Einleitung eines Gesetzgebungsverfahrens auf Initiative der Abgeordneten),  (ii) [[Regierungsvorlage]] (dies ist ein Gesetzesantrag, der von der [[Bundesregierung]] vorbereitet und nach Abstimmung im [[Ministerrat]] in den Nationalrat eingebracht wird. Regierungsvorlagen sind häufig, da die [[Exekutive]] oft die politische Initiative in der Gesetzgebung übernimmt),  (iii) [[Volksbegehren]] (ein Gesetzesantrag kann auch durch ein Volksbegehren eingebracht werden, wenn es die notwendige Anzahl von Unterschriften erhält. Das Parlament ist dann verpflichtet, sich mit dem Anliegen zu befassen)"}, {"kategorie": "", "text": "Der Gesetzesantrag wird formell im Nationalrat eingereicht"}, {"kategorie": "", "text": "Erste [[Lesung]]: Der Antrag wird im [[Plenum]] des Nationalrats in einer ersten Lesung vorgestellt und anschließend zur detaillierten Beratung an den zuständigen [[Fachausschuss]] verwiesen"}, {"kategorie": "", "text": "[[Ausschussberatung]]: Im [[Ausschuss]] wird der Antrag geprüft und gegebenenfalls angepasst"}, {"kategorie": "", "text": "Zweite und Dritte Lesung: Nach der [[Ausschussberatung]] kommt der [[Antrag]] erneut ins [[Plenum]], wo er in der zweiten Lesung diskutiert und in der dritten Lesung zur Abstimmung gestellt wird"}, {"kategorie": "", "text": "Beschluss und Inkrafttreten: Nach der Annahme durch den Nationalrat muss das Gesetz noch vom [[Bundesrat]] und schließlich vom [[Bundespräsidenten]] geprüft und unterzeichnet werden, bevor es durch Veröffentlichung im [[Bundesgesetzblatt]] in Kraft tritt."}]'::jsonb, ''),
  ('entschliissungsauntroog', 'Entschliißungsauntroog', '', '', '', '', 'Entschließungsantrag', '[{"kategorie": "pol.", "text": "\"Antrag, der darauf abzielt, das [[Parlament]] ([[Nationalrat]] oder [[Bundesrat]]) aufzufordern, eine [[Resolution]] zu einem bestimmten Thema zu verabschieden\""}, {"kategorie": "", "text": "Der Antrag fordert typischerweise die [[Regierung]] oder eine staatliche Institution dazu auf, bestimmte Maßnahmen zu ergreifen, oder äußert die politische Meinung des Parlaments zu einem bestimmten Thema"}, {"kategorie": "", "text": "Im Gegensatz zu [[Gesetzesanträgen]] hat ein Entschließungsantrag keine direkte rechtliche Verbindlichkeit. Er dient eher dazu, die politische Haltung des Parlaments zu einem Thema zu verdeutlichen oder Druck auf die Regierung auszuüben"}, {"kategorie": "", "text": "Der Entschließungsantrag wird von [[Abgeordneten]] eingebracht und kann Themen betreffen, die nationale, internationale oder gesellschaftliche Relevanz haben. Die Abgeordneten äußern damit ihren Wunsch, dass die Regierung bestimmte Maßnahmen in einem Bereich ergreifen oder Position beziehen soll"}, {"kategorie": "", "text": "Nach der Einbringung wird der Entschließungsantrag im [[Plenum]] debattiert und darüber abgestimmt. Falls eine Mehrheit zustimmt, wird die Entschließung angenommen, und die Aufforderung wird an die zuständige Institution weitergeleitet"}, {"kategorie": "", "text": "Beispiele für Entschließungsanträge: (i) Aufforderungen an die [[Bundesregierung]], sich auf europäischer Ebene für bestimmte Umweltstandards einzusetzen,  (ii) Aufforderung an die [[Regierung]], sich intensiver mit Fragen der Armutsbekämpfung auseinanderzusetzen,  (iii) Politische Stellungnahmen zu internationalen Konflikten oder Menschenrechtsfragen"}, {"kategorie": "", "text": "Zusammengefasst ist ein Entschließungsantrag ein Mittel, durch das das Parlament seine politische Meinung äußern oder Maßnahmen von der Regierung fordern kann, ohne dabei unmittelbare rechtliche Folgen zu erzeugen."}]'::jsonb, ''),
  ('auntroog', 'Auntroog', '', '', '', '', 'Antrag', '[{"kategorie": "pol.", "text": "\"ein formelles Begehren oder eine Vorschlagsinitiative, die von [[Abgeordneten]] des [[Nationalrats]] oder [[Bundesrats]] eingebracht wird, um eine bestimmte Maßnahme, Entscheidung oder Beschlussfassung anzustoßen\""}, {"kategorie": "", "text": "Anträge können sich auf eine Vielzahl von Themen beziehen, einschließlich der Gesetzgebung, Verwaltung oder politischen [[Resolutionen]], und sind ein wichtiges Instrument der parlamentarischen Arbeit"}, {"kategorie": "", "text": "Arten von Anträgen: (i) [[Gesetzesantrag]] (dies ist ein Vorschlag, ein neues Gesetz zu erlassen oder ein bestehendes Gesetz zu ändern. Der Antrag wird von Abgeordneten eingebracht und muss den formalen [[Gesetzgebungsprozess]] durchlaufen, einschließlich Beratungen im [[Ausschuss]] und Abstimmungen im [[Plenum]]),  (ii) [[Entschließungsantrag]] (durch einen solchen Antrag wird das [[Parlament]] aufgefordert, eine politische [[Resolution]] zu beschließen. Der Entschließungsantrag fordert die Regierung in der Regel auf, eine bestimmte Maßnahme zu ergreifen oder eine Position zu beziehen, hat jedoch keine rechtlich bindende Wirkung,  (iii) Antrag auf Untersuchungsausschuss (mit diesem Antrag kann die Einsetzung eines [[Untersuchungsausschusses]] verlangt werden, um bestimmte Sachverhalte zu untersuchen, beispielsweise mutmaßliche Missstände oder Fehlverhalten in der Verwaltung oder Politik);  (iv) Verfahrensanträge (diese betreffen die organisatorische Arbeit des [[Parlaments]], wie etwa der Antrag auf Vertagung einer Debatte oder die Änderung der Tagesordnung)"}, {"kategorie": "", "text": "Anträge werden in der Regel von einer Gruppe von Abgeordneten eingebracht und müssen im Nationalrat oder Bundesrat debattiert werden. Je nach Art des Antrags wird über den Vorschlag abgestimmt, und bei Zustimmung tritt der Antrag in Kraft oder leitet den entsprechenden nächsten Schritt ein (z. B. den [[Gesetzgebungsprozess]] oder die [[Resolution]])."}]'::jsonb, ''),
  ('resolution', 'Resolution', '', '', '', '', 'Resolution', '[{"kategorie": "pol.", "text": "\"politischer Beschluss, der vom [[Nationalrat]] oder [[Bundesrat]] gefasst wird\""}, {"kategorie": "", "text": "Im Unterschied zu einem [[Gesetz]] hat eine Resolution keine rechtlich bindende Wirkung. Stattdessen dient sie dazu, politische Meinungen, Forderungen oder Empfehlungen auszudrücken. Durch eine Resolution kann das [[Parlament]] seine Haltung zu einem bestimmten Thema klarstellen oder die Regierung auffordern, bestimmte Maßnahmen zu ergreifen"}, {"kategorie": "", "text": "Resolutionen werden oft von [[Abgeordneten]] des Nationalrats eingebracht. Diese können sich auf nationale oder internationale Themen beziehen und dienen dazu, die Position des Parlaments zu einem bestimmten Sachverhalt öffentlich klarzustellen"}, {"kategorie": "", "text": "Resolutionen werden im Nationalrat oder Bundesrat besprochen und nach einer Debatte abgestimmt. Die Annahme einer Resolution signalisiert, dass eine Mehrheit der Abgeordneten eine bestimmte politische Richtung unterstützt"}, {"kategorie": "", "text": "Eine Resolution kann die [[Regierung]] beispielsweise dazu auffordern, sich auf europäischer Ebene für bestimmte Änderungen in der Umweltpolitik einzusetzen"}, {"kategorie": "", "text": "Auch im internationalen Kontext kann das Parlament Resolutionen verabschieden, etwa um gegen Menschenrechtsverletzungen in anderen Ländern zu protestieren"}, {"kategorie": "", "text": "Insgesamt sind Resolutionen in der österreichischen Politik ein Instrument der politischen Meinungsäußerung, die nicht bindend, aber dennoch von großer politischer Relevanz sein können​"}]'::jsonb, ''),
  ('nationalroodspraesident', 'Nationalroodspräsident', '', '', '', '', 'Nationalratspräsident', '[{"kategorie": "pol.", "text": "\"Vorsitzender des [[Nationalrats]] (des [[Parlaments]] der [[Republik]] Österreich) und damit eine der höchsten politischen Ämter im Land\""}, {"kategorie": "", "text": "Der Nationalratspräsident ist verantwortlich für die Leitung der Sitzungen des Nationalrats und spielt eine wichtige Rolle in der Sicherstellung eines geordneten und fairen Ablaufs der parlamentarischen Arbeit"}, {"kategorie": "", "text": "Der Nationalratspräsident leitet die [[Plenarsitzungen]] des Nationalrats und sorgt dafür, dass die Regeln der Geschäftsordnung eingehalten werden. Er gewährleistet, dass die Debatten fair und ordnungsgemäß verlaufen, und erteilt den Abgeordneten das Wort"}, {"kategorie": "", "text": "Der Nationalratspräsident vertritt den Nationalrat nach außen, sowohl gegenüber anderen Staatsorganen als auch international. Er nimmt an offiziellen Anlässen teil und fördert die parlamentarischen Beziehungen zu anderen Ländern"}, {"kategorie": "", "text": "Er hat das Recht, Ordnungsmaßnahmen zu ergreifen, wenn Abgeordnete gegen die Geschäftsordnung verstoßen. Dies kann beispielsweise Verwarnungen oder den Ausschluss von der Sitzung beinhalten"}, {"kategorie": "", "text": "Obwohl der Nationalratspräsident in der Regel aus der stärksten Fraktion des Nationalrats kommt, ist es seine Pflicht, eine überparteiliche Rolle zu spielen und alle Abgeordneten gleich zu behandeln. Er soll sicherstellen, dass die parlamentarischen Prozesse neutral und fair ablaufen"}, {"kategorie": "", "text": "Der Nationalratspräsident ist Teil des Präsidiums des Nationalrats, das aus dem Präsidenten und seinen zwei Stellvertretern besteht. Das Präsidium koordiniert die Abläufe im Nationalrat und berät über wichtige organisatorische Fragen"}, {"kategorie": "", "text": "Der Nationalratspräsident wird von den Abgeordneten des Nationalrats in der [[konstituierenden]] Sitzung nach den Wahlen gewählt. In der Regel stammt der Präsident aus der stärksten Fraktion des Parlaments, was ihm eine repräsentative Bedeutung gibt."}]'::jsonb, ''),
  ('bundesvafossung', 'Bundesvafossung', '', '', '', '', 'Bundesverfassung', '[{"kategorie": "", "text": "Sie regelt die Staatsorganisation, die [[Gewaltenteilung]], die Rechte und Pflichten der Bürger sowie die Kompetenzen zwischen [[Bund]] und Ländern"}, {"kategorie": "", "text": "Die österreichische Bundesverfassung trat erstmals im Oktober 1920 in Kraft und wurde unter der Leitung des Rechtsgelehrten [[Hans]] Kelsen ausgearbeitet"}, {"kategorie": "", "text": "Die Bundesverfassung teilt die [[Staatsgewalt]] in [[Legislative]] (gesetzgebende Gewalt), [[Exekutive]] (ausführende Gewalt) und [[Judikative]] (rechtsprechende Gewalt) auf. Die Legislative besteht aus dem [[Nationalrat]] (direkt gewähltes Parlament) und dem [[Bundesrat]] (Vertretung der Bundesländer). Die Exekutive wird vom [[Bundespräsidenten]] und der [[Bundesregierung]] ausgeübt"}, {"kategorie": "", "text": "Österreich ist ein föderaler Staat, was bedeutet, dass die Verfassung die Kompetenzen zwischen dem Bund und den neun Bundesländern aufteilt. Die Länder haben eigene Verfassungen und Verwaltungen, während bestimmte Kompetenzen (z. B. Außenpolitik, Verteidigung) beim [[Bund]] liegen"}, {"kategorie": "", "text": "Die Bundesverfassung schützt die [[Grundrechte]] der Bürger, wie etwa die Meinungsfreiheit, Glaubensfreiheit und den Schutz der persönlichen Freiheit. Diese Grundrechte bilden die Basis für die [[Rechtsstaatlichkeit]] und [[demokratische]] Ordnung"}, {"kategorie": "", "text": "Die Änderung der Bundesverfassung ist möglich, erfordert jedoch eine Zweidrittelmehrheit im Nationalrat. Bestimmte besonders wichtige Bestimmungen können nur durch eine [[Volksabstimmung]] geändert werden"}, {"kategorie": "", "text": "Die österreichische Bundesverfassung wurde seit 1920 mehrfach reformiert und ergänzt, bleibt jedoch in ihrem Grundprinzip bestehen."}]'::jsonb, ''),
  ('legislatuaperiode', 'Legislatuaperiode', '', '', '', '', 'Legislaturperiode', '[{"kategorie": "pol.", "text": "\"Zeitraum, in dem ein gewähltes [[Parlament]] tätig ist, bevor eine Neuwahl stattfindet\""}, {"kategorie": "", "text": "In Österreich dauert eine Legislaturperiode des [[Nationalrats]] grundsätzlich fünf Jahre. Während dieser Zeit arbeitet das Parlament an der Gesetzgebung, der Kontrolle der Regierung und der Vertretung der Interessen der Bürger"}, {"kategorie": "", "text": "Die Legislaturperiode beginnt mit der [[konstituierenden]] Sitzung des neu gewählten Nationalrats, die nach den Nationalratswahlen stattfindet"}, {"kategorie": "", "text": "In Österreich beträgt die normale Dauer einer Legislaturperiode fünf Jahre, es sei denn, der Nationalrat wird vorzeitig aufgelöst und es kommt zu Neuwahlen. Die fünfjährige Amtsperiode ist durch die [[Bundesverfassung]] festgelegt"}, {"kategorie": "", "text": "Die Legislaturperiode endet mit der Auflösung des Nationalrats, entweder nach Ablauf der regulären fünf Jahre oder durch vorzeitige Auflösung, etwa durch ein [[Misstrauensvotum]] oder eine freiwillige Auflösung des Parlaments"}, {"kategorie": "", "text": "Während einer Legislaturperiode sind die [[Abgeordneten]] des Nationalrats dafür zuständig, Gesetze zu verabschieden, die [[Regierung]] zu kontrollieren und die Interessen der Bevölkerung zu vertreten. Die Legislaturperiode bietet eine stabile Zeitspanne, in der politische Vorhaben umgesetzt werden können."}]'::jsonb, ''),
  ('plenarsitzung', 'Plenarsitzung', '', '', '', '', 'Plenarsitzung', '[{"kategorie": "pol.", "text": "\"Vollversammlung des [[Nationalrats]] oder des [[Bundesrats]], in der alle [[Abgeordneten]] zusammenkommen, um über [[Gesetzesvorlagen]], politische Anträge und andere wichtige Angelegenheiten zu diskutieren und abzustimmen\""}, {"kategorie": "", "text": "Sie ist das zentrale Forum, in dem die wesentlichen politischen Debatten und Entscheidungen getroffen werden"}, {"kategorie": "", "text": "Alle Abgeordneten des Nationalrats (183 Mitglieder) oder des Bundesrats nehmen an einer Plenarsitzung teil. Die Sitzungen sind meist öffentlich und bieten den Abgeordneten die Möglichkeit, ihre Standpunkte zu den vorgeschlagenen Gesetzen und politischen Maßnahmen darzulegen"}, {"kategorie": "", "text": "Die Plenarsitzung wird vom [[Nationalratspräsidenten]] (oder seinem Stellvertreter) geleitet, der für den geordneten Ablauf der Sitzung sorgt. Er erteilt das Wort, stellt die Tagesordnung vor und sorgt für die Einhaltung der Geschäftsordnung"}, {"kategorie": "", "text": "In Plenarsitzungen finden die [[Lesungen]] von [[Gesetzesentwürfen]] statt, die zuvor in den [[Fachausschüssen]] beraten wurden. Nach der Diskussion im [[Plenum]] wird über die Gesetze abgestimmt, und bei einer Mehrheit treten sie in die nächste Phase des [[Gesetzgebungsverfahrens]] ein"}, {"kategorie": "", "text": "Die Plenarsitzungen sind öffentlich und können in der Regel von Bürgern besucht oder über Livestreams im Internet verfolgt werden. Dies dient der Transparenz und ermöglicht es der Öffentlichkeit, die Arbeit der Abgeordneten nachzuvollziehen"}, {"kategorie": "", "text": "Am Ende der Plenarsitzung erfolgt die Abstimmung über die besprochenen Gesetzesvorlagen und [[Anträge]]. Diese Abstimmungen sind entscheidend, da sie die endgültige Entscheidung darüber bringen, ob ein Gesetz angenommen, abgelehnt oder abgeändert wird."}]'::jsonb, ''),
  ('plenum', 'Plenum', '', '', '', '', 'Plenum', '[{"kategorie": "pol.", "text": "\"die Vollversammlung des [[Nationalrats]] oder des [[Bundesrats]], in der alle [[Abgeordneten]] zusammenkommen, um über [[Gesetzesvorlagen]], Anträge oder andere politische Themen zu diskutieren und abzustimmen\""}, {"kategorie": "", "text": "Das Plenum ist das höchste Gremium des [[Parlaments]] und der zentrale Ort der parlamentarischen Arbeit. Im Plenum finden die wesentlichen politischen Debatten statt, und dort werden letztlich die Entscheidungen getroffen, die für die gesamte Bevölkerung bindend sind"}, {"kategorie": "", "text": "Im Plenum sind alle Abgeordneten des Nationalrats oder des Bundesrats vertreten. Im Nationalrat sitzen derzeit 183 Abgeordnete, die vom Volk gewählt wurden, während der Bundesrat die Interessen der Bundesländer vertritt"}, {"kategorie": "", "text": "[[Gesetzesentwürfe]] werden im Plenum diskutiert und in mehreren [[Lesungen]] behandelt. Die finale Abstimmung über ein [[Gesetz]] findet immer im Plenum statt, nachdem es in den [[Fachausschüssen]] geprüft wurde"}, {"kategorie": "", "text": "Die Sitzungen des Plenums sind in der Regel öffentlich, was bedeutet, dass Bürger und Medien die Diskussionen verfolgen können. Dies dient der Transparenz des politischen Entscheidungsprozesses"}, {"kategorie": "", "text": "Im Plenum wird über [[Gesetzesvorlagen]], [[Anträge]], [[Resolutionen]] und andere politische Entscheidungen abgestimmt. Die Beschlüsse des Plenums sind für die Regierung und alle staatlichen Institutionen bindend"}, {"kategorie": "", "text": "Die Sitzungen des Nationalratsplenums werden vom [[Nationalratspräsidenten]] geleitet, der für den geordneten Ablauf der Debatten sorgt.​"}]'::jsonb, ''),
  ('fochausschuss', 'Fochausschuss', '', '', '', '', 'Fachausschuss', '[{"kategorie": "pol.", "text": "\"kleine Gruppe von [[Abgeordneten]] des [[Nationalrats]], die sich auf bestimmte Politikbereiche spezialisiert haben und Gesetzesentwürfe detailliert prüfen, bevor diese im [[Plenum]] des Nationalrats zur Abstimmung kommen\""}, {"kategorie": "", "text": "Fachausschüsse sind für die inhaltliche Ausarbeitung und Bewertung von Gesetzen verantwortlich und spielen eine zentrale Rolle bei der Sicherstellung, dass [[Gesetze]] umfassend diskutiert und analysiert werden"}, {"kategorie": "", "text": "Jeder Fachausschuss ist für ein bestimmtes Themengebiet zuständig, wie z. B. Finanzen, Gesundheit, Bildung oder Verkehr. Die Abgeordneten, die im jeweiligen Ausschuss sitzen, sind in diesem Bereich erfahren oder spezialisiert"}, {"kategorie": "", "text": "Sobald ein [[Gesetzesentwurf]] im Nationalrat eingebracht und in der ersten [[Lesung]] diskutiert wurde, wird der Entwurf an den zuständigen Fachausschuss weitergeleitet. Hier erfolgt die detaillierte Beratung, in der der Entwurf inhaltlich analysiert und gegebenenfalls geändert wird"}, {"kategorie": "", "text": "Während der [[Ausschussberatungen]] können Experten, Interessenvertreter oder Betroffene angehört werden, um zusätzliche Informationen zu erhalten und die Qualität des Gesetzes zu verbessern. Die Fachausschüsse können auch Änderungen vorschlagen oder Gesetze in ihrer ursprünglichen Form zur Annahme empfehlen"}, {"kategorie": "", "text": "Nach Abschluss der Beratungen erstellt der [[Fachausschuss]] einen Bericht, der dem Nationalrat vorgelegt wird. Dieser Bericht enthält die Empfehlungen des Ausschusses, ob der Entwurf angenommen, abgelehnt oder geändert werden soll"}, {"kategorie": "", "text": "Fachausschüsse können sowohl öffentliche als auch nicht-öffentliche Sitzungen abhalten. Bei wichtigen oder kontroversen Themen können öffentliche Anhörungen stattfinden, um die Transparenz zu erhöhen."}]'::jsonb, ''),
  ('ausschuss', 'Ausschuss', '', '', '', '', 'Ausschuss', '[{"kategorie": "", "text": "Fachausschüsse sind für die inhaltliche Ausarbeitung und Bewertung von Gesetzen verantwortlich und spielen eine zentrale Rolle bei der Sicherstellung, dass [[Gesetze]] umfassend diskutiert und analysiert werden"}, {"kategorie": "", "text": "Jeder Fachausschuss ist für ein bestimmtes Themengebiet zuständig, wie z. B. Finanzen, Gesundheit, Bildung oder Verkehr. Die Abgeordneten, die im jeweiligen Ausschuss sitzen, sind in diesem Bereich erfahren oder spezialisiert"}, {"kategorie": "", "text": "Sobald ein [[Gesetzesentwurf]] im Nationalrat eingebracht und in der ersten [[Lesung]] diskutiert wurde, wird der Entwurf an den zuständigen Fachausschuss weitergeleitet. Hier erfolgt die detaillierte Beratung, in der der Entwurf inhaltlich analysiert und gegebenenfalls geändert wird"}, {"kategorie": "", "text": "Während der [[Ausschussberatungen]] können Experten, Interessenvertreter oder Betroffene angehört werden, um zusätzliche Informationen zu erhalten und die Qualität des Gesetzes zu verbessern. Die Fachausschüsse können auch Änderungen vorschlagen oder Gesetze in ihrer ursprünglichen Form zur Annahme empfehlen"}, {"kategorie": "", "text": "Nach Abschluss der Beratungen erstellt der [[Fachausschuss]] einen Bericht, der dem Nationalrat vorgelegt wird. Dieser Bericht enthält die Empfehlungen des Ausschusses, ob der Entwurf angenommen, abgelehnt oder geändert werden soll"}, {"kategorie": "", "text": "Fachausschüsse können sowohl öffentliche als auch nicht-öffentliche Sitzungen abhalten. Bei wichtigen oder kontroversen Themen können öffentliche Anhörungen stattfinden, um die Transparenz zu erhöhen."}]'::jsonb, ''),
  ('lesung', 'Lesung', '', '', '', '', 'Lesung', '[{"kategorie": "pol.", "text": "\"formelle Beratung eines [[Gesetzesentwurfs]] oder [[Initiativantrags]]\""}, {"kategorie": "", "text": "Der [[Gesetzgebungsprozess]] im [[Nationalrat]] umfasst in der Regel drei Lesungen, die jeweils unterschiedliche Phasen der Diskussion und Prüfung des vorgeschlagenen [[Gesetzes]] abdecken"}, {"kategorie": "", "text": "Die Lesungen sind ein zentraler Bestandteil des parlamentarischen Verfahrens, um sicherzustellen, dass [[Gesetzesvorschläge]] gründlich geprüft, diskutiert und abgestimmt werden, bevor sie in Kraft treten können"}, {"kategorie": "i", "text": "Erste Lesung: In der ersten Lesung wird der Gesetzesentwurf im Nationalrat grundsätzlich vorgestellt. Es erfolgt eine allgemeine Diskussion über das Vorhaben, und es wird entschieden, ob der Entwurf an einen [[Ausschuss]] überwiesen wird, wo er detailliert bearbeitet wird. Die erste Lesung findet oft ohne ausführliche Debatte statt, außer es handelt sich um besonders wichtige oder kontroverse Themen:  (ii) Zweite Lesung: In der zweiten Lesung wird der Gesetzesentwurf detailliert diskutiert. Hierbei werden die Ergebnisse der [[Ausschussberatung]] präsentiert, und Abänderungsanträge können eingebracht werden. Es gibt eine Generaldebatte über das gesamte Gesetz und anschließend eine Spezialdebatte, in der einzelne Paragraphen und Details des Gesetzes erörtert werden;  (iii) Dritte Lesung: Die dritte Lesung ist in der Regel eine kurze formelle Lesung, bei der über den gesamten Gesetzesentwurf in seiner endgültigen Fassung abgestimmt wird. Nach der dritten Lesung findet die Schlussabstimmung statt. Wenn der Gesetzesentwurf eine Mehrheit erhält, wird er angenommen und an den [[Bundesrat]] zur weiteren Prüfung übermittelt"}, {"kategorie": "", "text": "Die Lesungen im Nationalrat dienen dazu, die [[Gesetzesentwürfe]] gründlich zu prüfen, unterschiedliche Meinungen zu diskutieren und sicherzustellen, dass alle Abgeordneten die Möglichkeit haben, Änderungen vorzuschlagen oder sich zur [[Gesetzesvorlage]] zu äußern. Sie gewährleisten, dass der [[Gesetzgebungsprozess]] transparent und demokratisch abläuft und das [[Parlament]] in der Gesetzgebung eine zentrale Rolle spielt"}]'::jsonb, ''),
  ('initiativauntroog', 'Initiativauntroog', '', '', '', '', 'Initiativantrag', '[{"kategorie": "pol.", "text": "\"Gesetzesvorschlag, der von [[Abgeordneten]] des [[Nationalrats]] oder des [[Landtags]] (auf Länderebene) eingebracht wird, um neue Gesetze zu initiieren oder bestehende Gesetze zu ändern\""}, {"kategorie": "", "text": "Der Initiativantrag ist ein wichtiges Instrument der Gesetzgebung, das den Abgeordneten ermöglicht, direkt an der Ausarbeitung und Vorschlagserstellung von [[Gesetzen]] teilzunehmen, ohne dass die Initiative von der Regierung ausgehen muss"}, {"kategorie": "", "text": "Anders als eine [[Regierungsvorlage]], die von der [[Bundesregierung]] eingebracht wird, stammt der Initiativantrag von den Mitgliedern des [[Parlaments]] selbst. Eine bestimmte Anzahl von Abgeordneten (mindestens fünf im Nationalrat) ist erforderlich, um einen solchen Antrag einzubringen"}, {"kategorie": "", "text": "Der Initiativantrag bietet die Möglichkeit, Gesetze auch außerhalb der [[Exekutive]] vorzuschlagen. Dies stärkt die Rolle der [[Legislative]] und ermöglicht es, auch Themen auf die Agenda zu setzen, die nicht Teil der Regierungspolitik sind"}, {"kategorie": "", "text": "Nach der Einbringung wird der Initiativantrag im Nationalrat diskutiert, ähnlich wie bei einer Regierungsvorlage. Der Antrag wird in [[Ausschüssen]] bearbeitet und durchläuft mehrere [[Lesungen]], bevor er zur Abstimmung kommt. Falls er eine Mehrheit erhält, wird er wie jedes andere [[Gesetz]] weiterverfolgt"}, {"kategorie": "", "text": "Initiativanträge können zu allen möglichen Themen gestellt werden, von sozialen Fragen bis hin zu Wirtschafts- oder Umweltgesetzen"}, {"kategorie": "", "text": "Der Initiativantrag ist ein bedeutendes Mittel der demokratischen Mitgestaltung, da er den [[Abgeordneten]] die Möglichkeit gibt, die politischen Themen und Gesetze aktiv zu beeinflussen, unabhängig von den Vorlagen der [[Regierung]]. Er trägt dazu bei, die Machtbalance zwischen Regierung und Parlament zu wahren und sicherzustellen, dass auch Themen, die vielleicht nicht auf der Regierungsagenda stehen, behandelt werden können."}]'::jsonb, ''),
  ('obgeoadneta', 'Obgeoadneta', '', '', '', '', 'Abgeordneter', '[{"kategorie": "pol.", "text": "\"gewähltes Mitglied des [[Nationalrats]] oder eines [[Landtags]], welches die Bürger in der [[Legislative]] vertritt\""}, {"kategorie": "", "text": "Abgeordnete haben die Aufgabe, Gesetze zu beraten, zu beschließen und die Regierung zu kontrollieren. Sie spielen eine zentrale Rolle im parlamentarischen System und sorgen dafür, dass die Interessen der Bevölkerung in den politischen Entscheidungsprozessen berücksichtigt werden"}, {"kategorie": "", "text": "Ein großer Teil der parlamentarischen Arbeit findet in [[Ausschüssen]] statt, in denen Gesetzesvorschläge detailliert geprüft und weiterentwickelt werden. Abgeordnete sind in verschiedenen Ausschüssen tätig, abhängig von ihrem Fachgebiet und den zu diskutierenden Themen"}, {"kategorie": "", "text": "Abgeordnete des [[Nationalrats]] werden bei allgemeinen Wahlen nach dem Prinzip der Verhältnismäßigkeit für eine Legislaturperiode von fünf Jahren gewählt. Die Abgeordneten des [[Landtags]] werden je nach Bundesland für unterschiedliche Zeiträume gewählt, üblicherweise ebenfalls für fünf Jahre"}, {"kategorie": "", "text": "Abgeordnete sind ein wichtiger Bestandteil der Demokratie in Österreich, da sie die gesetzgebende Gewalt repräsentieren und die Politik des Landes maßgeblich mitgestalten. Durch ihre Arbeit im Parlament tragen sie dazu bei, die Gesetze des Landes zu formen und das politische Gleichgewicht zwischen der [[Legislative]] und der [[Exekutive]] zu wahren."}]'::jsonb, ''),
  ('regiirungsvorlage', 'Regiirungsvorlage', '', '', '', '', 'Regierungsvorlage', '[{"kategorie": "pol.", "text": "\"Gesetzesentwurf, der von der [[Bundesregierung]] erarbeitet und beschlossen wird, bevor er dem [[Nationalrat]] zur Abstimmung vorgelegt wird\""}, {"kategorie": "", "text": "Sie ist eine der häufigsten Formen der Einbringung von [[Gesetzesentwürfen]] in das [[Parlament]] und spielt eine zentrale Rolle im [[Gesetzgebungsprozess]]"}, {"kategorie": "", "text": "Eine Regierungsvorlage wird in der Regel von einem oder mehreren Ministerien vorbereitet. Die zuständigen Bundesminister erarbeiten den Entwurf, oft in Abstimmung mit Fachleuten und Interessenvertretern, um sicherzustellen, dass der Entwurf sowohl juristisch als auch praktisch umsetzbar ist"}, {"kategorie": "", "text": "Bevor die Regierungsvorlage dem Nationalrat vorgelegt wird, muss sie im [[Ministerrat]] besprochen und von der gesamten Bundesregierung beschlossen werden. Dies stellt sicher, dass die Vorlage von der gesamten Regierung unterstützt wird"}, {"kategorie": "", "text": "Nach der Verabschiedung im Ministerrat wird die Regierungsvorlage dem Nationalrat zur Beratung und Abstimmung vorgelegt. Dort durchläuft sie das gesetzliche Verfahren, das mehrere [[Lesungen]] und [[Ausschussberatungen]] umfasst"}, {"kategorie": "", "text": "Die Regierungsvorlage wird im Nationalrat behandelt, wo sie in mehreren Schritten diskutiert, angepasst und schließlich zur Abstimmung gestellt wird. Nach der Verabschiedung durch den Nationalrat wird das Gesetz dem [[Bundesrat]] vorgelegt, der die Vorlage billigen oder ablehnen kann"}, {"kategorie": "", "text": "Abschließend muss der [[Bundespräsident]] das [[Gesetz]] unterzeichnen, bevor es im [[Bundesgesetzblatt]] veröffentlicht und damit rechtskräftig wird."}]'::jsonb, ''),
  ('gesetzblott', 'Gesetzblott', '', '', '', '', 'Gesetzblatt', '[{"kategorie": "", "text": "Es dient dazu, [[Gesetze]] und Rechtsvorschriften rechtskräftig zu machen und der Öffentlichkeit zugänglich zu machen. Ein Gesetz tritt in Österreich erst in Kraft, wenn es im Bundesgesetzblatt veröffentlicht wurde"}, {"kategorie": "", "text": "Das Bundesgesetzblatt wird in elektronischer Form auf der offiziellen Website der Republik Österreich veröffentlicht und ist für die Öffentlichkeit einsehbar"}, {"kategorie": "", "text": "Im Bundesgesetzblatt werden verschiedene Arten von Rechtsakten veröffentlicht, darunter (i) Bundesgesetze (neue Gesetze oder Gesetzesänderungen, die vom Nationalrat beschlossen wurden),  (ii) Verordnungen (Rechtsakte, die von Regierungsstellen zur näheren Ausführung von Gesetzen erlassen werden),  (iii) Völkerrechtliche Verträge (internationale Abkommen und Verträge, die für Österreich bindend sind)"}, {"kategorie": "", "text": "Das Bundesgesetzblatt ist in mehrere Teile gegliedert: (i) Teil I (enthält die verfassungsgesetzlich erforderlichen Veröffentlichungen, insbesondere neue Gesetze und Gesetzesänderungen), (ii) Teil II: (umfasst Verordnungen und sonstige Regelungen, die von Behörden erlassen werden), (iii) Teil III (hier werden völkerrechtliche Verträge und internationale Abkommen veröffentlicht)"}, {"kategorie": "", "text": "Das Bundesgesetzblatt spielt eine zentrale Rolle im österreichischen [[Rechtsstaat]], da es sicherstellt, dass alle Gesetze und Verordnungen ordnungsgemäß veröffentlicht und für die Bürger zugänglich gemacht werden. Nur durch die Veröffentlichung im Bundesgesetzblatt können Rechtsakte verbindlich werden und ihre rechtliche Wirkung entfalten."}]'::jsonb, ''),
  ('bundesgesetzblott', 'Bundesgesetzblott', '', '', '', '', 'Bundesgesetzblatt', '[{"kategorie": "pol.", "text": "\"offizielles Publikationsorgan der [[Republik]] Österreich, in dem alle [[Bundesgesetze]], [[Verordnungen]] und sonstigen rechtlich relevanten Texte veröffentlicht werden\""}, {"kategorie": "", "text": "Es dient dazu, [[Gesetze]] und Rechtsvorschriften rechtskräftig zu machen und der Öffentlichkeit zugänglich zu machen. Ein Gesetz tritt in Österreich erst in Kraft, wenn es im Bundesgesetzblatt veröffentlicht wurde"}, {"kategorie": "", "text": "Das Bundesgesetzblatt wird in elektronischer Form auf der offiziellen Website der Republik Österreich veröffentlicht und ist für die Öffentlichkeit einsehbar"}, {"kategorie": "", "text": "Im Bundesgesetzblatt werden verschiedene Arten von Rechtsakten veröffentlicht, darunter (i) Bundesgesetze (neue Gesetze oder Gesetzesänderungen, die vom Nationalrat beschlossen wurden),  (ii) Verordnungen (Rechtsakte, die von Regierungsstellen zur näheren Ausführung von Gesetzen erlassen werden),  (iii) Völkerrechtliche Verträge (internationale Abkommen und Verträge, die für Österreich bindend sind)"}, {"kategorie": "", "text": "Das Bundesgesetzblatt ist in mehrere Teile gegliedert: (i) Teil I (enthält die verfassungsgesetzlich erforderlichen Veröffentlichungen, insbesondere neue Gesetze und Gesetzesänderungen), (ii) Teil II: (umfasst Verordnungen und sonstige Regelungen, die von Behörden erlassen werden), (iii) Teil III (hier werden völkerrechtliche Verträge und internationale Abkommen veröffentlicht)"}, {"kategorie": "", "text": "Das Bundesgesetzblatt spielt eine zentrale Rolle im österreichischen [[Rechtsstaat]], da es sicherstellt, dass alle Gesetze und Verordnungen ordnungsgemäß veröffentlicht und für die Bürger zugänglich gemacht werden. Nur durch die Veröffentlichung im Bundesgesetzblatt können Rechtsakte verbindlich werden und ihre rechtliche Wirkung entfalten."}]'::jsonb, ''),
  ('gesetzesvorschlog', 'Gesetzesvorschlog', '', '', '', '', 'Gesetzesvorschlag', '[{"kategorie": "", "text": "Sie bildet den ersten Schritt im [[Gesetzgebungsverfahren]], das mit der Beratung und Abstimmung im [[Parlament]] beginnt und schließlich zur Umsetzung in der Praxis führen kann"}, {"kategorie": "", "text": "Eine Gesetzesvorlage kann von der Bundesregierung (als sogenannte [[Regierungsvorlage]]), von den [[Abgeordneten]] des Nationalrats (Initiativanträge), von Mitgliedern des [[Bundesrats]] oder durch [[Volksbegehren]] eingebracht werden"}, {"kategorie": "", "text": "Die Gesetzesvorlage wird im Nationalrat in drei [[Lesungen]] behandelt. In diesen Lesungen wird der Entwurf diskutiert, Änderungen vorgeschlagen und schließlich darüber abgestimmt"}, {"kategorie": "", "text": "Nach der Beratung und gegebenenfalls Änderungen erfolgt die Abstimmung im Nationalrat. Bei einer Mehrheit wird die Gesetzesvorlage angenommen"}, {"kategorie": "", "text": "Nach der Annahme im Nationalrat wird die Gesetzesvorlage dem Bundesrat zur Zustimmung übermittelt. In seltenen Fällen kann der Bundesrat ein Veto einlegen"}, {"kategorie": "", "text": "Abschließend muss das Gesetz vom [[Bundespräsidenten]] unterzeichnet werden, bevor es veröffentlicht und rechtskräftig wird"}, {"kategorie": "", "text": "In Österreich sind [[Regierungsvorlagen]] die häufigste Form von Gesetzesvorlagen, da die [[Bundesregierung]] oft die politische Initiative für gesetzliche Änderungen übernimmt​"}]'::jsonb, ''),
  ('bescheid', 'Bescheid', '', '', '', '', 'Bescheid', '[{"kategorie": "jur.", "text": "\"amtliche Entscheidung, die von einer [[Verwaltungsbehörde]] erlassen wird und die konkrete Rechtsfolgen für den Adressaten hat\""}, {"kategorie": "", "text": "Der Bescheid ist eine individuelle Anordnung im Rahmen eines Verwaltungsverfahrens, die eine Rechtsfrage für einen bestimmten Einzelfall verbindlich regelt"}, {"kategorie": "", "text": "Bescheide werden typischerweise erlassen, wenn ein Bürger oder eine Institution einen Antrag an die Behörde stellt (z. B. eine Baugenehmigung, Sozialhilfe oder Gewerbeberechtigung) oder wenn die Behörde von sich aus handelt"}, {"kategorie": "", "text": "Ein Bescheid hat rechtlich bindende Wirkung für den Adressaten, der sich an die darin festgelegten Bestimmungen halten muss"}, {"kategorie": "", "text": "Bescheide müssen in der Regel schriftlich ergehen und klar die rechtliche Grundlage, die Entscheidungsgründe und die festgelegten Rechte und Pflichten des Adressaten darlegen"}, {"kategorie": "", "text": "Der Bescheid enthält eine Rechtsmittelbelehrung, die dem Adressaten erklärt, welche Möglichkeiten er hat, gegen den Bescheid vorzugehen, falls er damit nicht einverstanden ist. Das Rechtsmittel ist üblicherweise eine Berufung oder Beschwerde, die bei einer übergeordneten Behörde oder einem Gericht eingebracht werden kann"}, {"kategorie": "", "text": "Arten von Bescheiden: (i) Genehmigungsbescheide (z. B. Bau-, Gewerbe- oder Betriebsgenehmigungen),  (ii) Ablehnungsbescheide (z. B. Ablehnung eines Antrags auf Sozialhilfe),  (iii) Strafbescheide (z. B. für Verwaltungsübertretungen wie Geschwindigkeitsübertretungen),  (iv) Feststellungsbescheide (z. B. zur Feststellung bestimmter Rechte oder Pflichten)"}, {"kategorie": "", "text": "Ein Bescheid wird im Rahmen eines [[Verwaltungsverfahrens]] erlassen. Dieses beginnt in der Regel mit einem Antrag des Bürgers oder einer Mitteilung der Behörde. Nach der Prüfung des Sachverhalts entscheidet die Behörde und erlässt daraufhin den Bescheid, der die rechtlichen Konsequenzen für den Einzelfall festlegt."}]'::jsonb, ''),
  ('beziakshauptmaunn', 'Beziakshauptmaunn', '', '', '', '', 'Bezirkshauptmann', '[{"kategorie": "pol.", "text": "\"Leiter einer [[Bezirkshauptmannschaft]], die als [[Verwaltungsbehörde]] auf Bezirksebene fungiert\""}, {"kategorie": "", "text": "Der Bezirkshauptmann ist eine hochrangige Beamtenposition und trägt die Verantwortung für die Organisation und Durchführung der Verwaltungsaufgaben im jeweiligen Bezirk. Er vertritt dabei sowohl Landes- als auch Bundesinteressen und sorgt dafür, dass [[Gesetze]] und [[Verordnungen]] auf regionaler Ebene korrekt umgesetzt werden"}, {"kategorie": "", "text": "Der Bezirkshauptmann leitet die Behörde und koordiniert die verschiedenen Abteilungen, die für unterschiedliche Verwaltungsbereiche zuständig sind, wie z. B. Sicherheit, Gesundheit, Bauwesen und Gewerbe"}, {"kategorie": "", "text": "Als Vertreter der [[Landesregierung]] im Bezirk ist der Bezirkshauptmann für die Vollziehung von Landesgesetzen zuständig. Er übernimmt auch Aufgaben des [[Bundes]], wenn diese delegiert wurden, wie etwa im Bereich des Verkehrs oder der inneren Sicherheit"}, {"kategorie": "", "text": "Der Bezirkshauptmann ist für die Sicherheitsverwaltung im Bezirk verantwortlich, einschließlich der Polizeiaufsicht und des Katastrophenschutzes"}, {"kategorie": "", "text": "Er hat die Entscheidungsbefugnis bei der Ausstellung von [[Bescheiden]] in Bereichen wie Bauwesen, Gewerbebetrieben, Verkehrsangelegenheiten und vielen anderen Verwaltungsbereichen"}, {"kategorie": "", "text": "Der Bezirkshauptmann ist eine zentrale Ansprechperson für die Bürger im Bezirk und sorgt dafür, dass Verwaltungsdienstleistungen effizient erbracht werden"}, {"kategorie": "", "text": "Der Bezirkshauptmann wird von der [[Landesregierung]] ernannt und steht in engem Austausch mit den politischen und administrativen Ebenen des Landes. Er sorgt dafür, dass die Verwaltung bürgernah und im Rahmen der geltenden Gesetze erfolgt."}]'::jsonb, '')
